// Файл сгенерирован: node ai-assistant/build-worker-assets.mjs — руками не править.
export const AI_ASSISTANT_HTML = "<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>ИИ-ассистент задач</title>\n<meta name=\"description\" content=\"Интерактивный разбор для воркшопа: как собрать ИИ-ассистента, который собирает задачи из чатов, лички, почты, календаря и CRM, следит за сроками, напоминает и отвечает на вопросы по всему контексту.\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Golos+Text:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n/* Layout: длинная страница-тренажёр, секции идут по пути задачи: источник → разбор → доска → напоминания → память → вопросы → сборка.\n   Стиль — как у прошлых воркшопов (/ai-notify): Golos Text + IBM Plex Mono, синий бренд, светлая и тёмная тема. */\n:root{\n  --bg:#F3F4F7; --card:#FFFFFF; --line:#E3E6EE; --line-soft:#EFF1F6; --sunk:#F7F8FB;\n  --ink:#101828; --ink-2:#525B6E; --ink-3:#8A93A6;\n  --brand:#2B4ACB; --brand-soft:#E9EDFC; --brand-ink:#1F38A0; --on-brand:#FFFFFF;\n  --good:#12805C; --good-soft:#E4F3ED;\n  --bad:#C4373C; --bad-soft:#FBEAEA;\n  --warn:#B7791F; --warn-soft:#FBF1DF;\n  --alt:#5B4BD6; --alt-soft:#EDEBFB;\n  --teal:#0E7C86; --teal-soft:#E2F1F2;\n  --chat:#E4EAF1; --out:#DDF3D1;\n  --shadow:0 1px 2px rgba(16,24,40,.05);\n  --shadow-pop:0 18px 48px rgba(16,24,40,.16);\n  --r-lg:12px; --r:9px; --r-sm:6px;\n  --sans:'Golos Text',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;\n  --mono:'IBM Plex Mono',ui-monospace,SFMono-Regular,Menlo,monospace;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --bg:#0D111C; --card:#151A28; --line:#262D40; --line-soft:#1C2232; --sunk:#111623;\n    --ink:#E7EAF2; --ink-2:#A6AEC2; --ink-3:#707A91;\n    --brand:#7F96F6; --brand-soft:#1D2646; --brand-ink:#AEBCFA; --on-brand:#0D111C;\n    --good:#4CC59A; --good-soft:#132D26; --bad:#F2777C; --bad-soft:#38191E;\n    --warn:#E5AE58; --warn-soft:#33281A; --alt:#A79AF6; --alt-soft:#252145;\n    --teal:#52C3CC; --teal-soft:#122C34; --chat:#0F1524; --out:#1F3A2C;\n    --shadow:0 1px 2px rgba(0,0,0,.3); --shadow-pop:0 18px 48px rgba(0,0,0,.5);\n    color-scheme:dark;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --bg:#0D111C; --card:#151A28; --line:#262D40; --line-soft:#1C2232; --sunk:#111623;\n  --ink:#E7EAF2; --ink-2:#A6AEC2; --ink-3:#707A91;\n  --brand:#7F96F6; --brand-soft:#1D2646; --brand-ink:#AEBCFA; --on-brand:#0D111C;\n  --good:#4CC59A; --good-soft:#132D26; --bad:#F2777C; --bad-soft:#38191E;\n  --warn:#E5AE58; --warn-soft:#33281A; --alt:#A79AF6; --alt-soft:#252145;\n  --teal:#52C3CC; --teal-soft:#122C34; --chat:#0F1524; --out:#1F3A2C;\n  --shadow:0 1px 2px rgba(0,0,0,.3); --shadow-pop:0 18px 48px rgba(0,0,0,.5);\n  color-scheme:dark;\n}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nhtml{-webkit-text-size-adjust:100%;scroll-behavior:smooth}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:14px;line-height:1.5;-webkit-font-smoothing:antialiased}\nh1,h2,h3,h4{margin:0;font-weight:600;letter-spacing:-.01em;text-wrap:balance}\np{margin:0}\nbutton{font:inherit;color:inherit;cursor:pointer}\ninput,textarea,select{font:inherit;color:inherit}\na{color:var(--brand)}\n:focus-visible{outline:2px solid var(--brand);outline-offset:2px}\n.wrap{max-width:1180px;margin:0 auto;padding-inline:24px}\n@media(max-width:560px){.wrap{padding-inline:16px}}\n.num,.mono{font-family:var(--mono);font-variant-numeric:tabular-nums}\n.muted{color:var(--ink-2)}\n.small{font-size:12.5px}\n\n/* sections */\nsection{padding-top:56px;scroll-margin-top:16px}\nmain > section:first-child{padding-top:36px}\n.sec-head{margin-bottom:18px;max-width:780px}\n.sec-head h2{font-size:24px;letter-spacing:-.02em}\n.sec-head p{margin-top:8px;color:var(--ink-2);font-size:14.5px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r-lg);box-shadow:var(--shadow)}\n.pad{padding:18px 20px}\n@media(max-width:560px){.pad{padding:14px}}\n.note{font-size:12.5px;color:var(--ink-3);margin-top:10px}\n\n/* buttons, chips */\n.btn{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:var(--card);border-radius:var(--r);padding:8px 13px;font-weight:500;font-size:13.5px;text-decoration:none;color:var(--ink);transition:background .15s,border-color .15s}\n.btn:hover{border-color:var(--ink-3)}\n.btn.primary{background:var(--brand);border-color:var(--brand);color:var(--on-brand)}\n.btn.primary:hover{background:var(--brand-ink);border-color:var(--brand-ink)}\n.btn.sm{padding:5px 10px;font-size:12.5px}\n.btn:disabled{opacity:.5;cursor:default}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chip{border:1px solid var(--line);background:var(--card);border-radius:999px;padding:5px 11px;font-size:12.5px;font-weight:500;color:var(--ink-2);text-align:left}\n.chip:hover{border-color:var(--ink-3);color:var(--ink)}\n.chip.on{background:var(--ink);border-color:var(--ink);color:var(--bg)}\n.tabs{display:flex;gap:4px;background:var(--sunk);border:1px solid var(--line);border-radius:10px;padding:3px;overflow-x:auto;scrollbar-width:none;max-width:100%}\n.tabs button{flex:none;border:0;background:transparent;border-radius:7px;padding:6px 12px;font-size:13px;font-weight:500;color:var(--ink-2);white-space:nowrap}\n.tabs button.on{background:var(--card);color:var(--ink);box-shadow:var(--shadow)}\n\n/* source badges */\n.src{display:inline-flex;align-items:center;font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.02em;padding:1px 6px;border-radius:5px;white-space:nowrap;background:var(--sunk);color:var(--ink-2);border:1px solid var(--line)}\n.src.s-tg{background:var(--teal-soft);color:var(--teal);border-color:transparent}\n.src.s-biz{background:var(--alt-soft);color:var(--alt);border-color:transparent}\n.src.s-mail{background:var(--warn-soft);color:var(--warn);border-color:transparent}\n.src.s-cal{background:var(--good-soft);color:var(--good);border-color:transparent}\n.src.s-crm{background:var(--brand-soft);color:var(--brand);border-color:transparent}\n.src.s-dash{background:var(--bad-soft);color:var(--bad);border-color:transparent}\n.src.s-voice{background:var(--sunk);color:var(--ink);border-color:var(--line)}\n\n/* map */\n.map{display:grid;grid-template-columns:minmax(0,1fr) 56px minmax(0,1fr) 56px minmax(0,1fr);align-items:stretch}\n.map .col{display:flex;flex-direction:column;gap:8px;min-width:0}\n.map .col h4{font-size:11.5px;text-transform:uppercase;letter-spacing:.06em;color:var(--ink-3);font-weight:600;margin-bottom:2px}\n.pipes{position:relative;display:flex;flex-direction:column;justify-content:space-around;padding-block:30px}\n.pipe.abs{position:absolute;left:0;right:0;margin-inline:6px}\n.pipe{height:2px;margin-inline:6px;background:repeating-linear-gradient(90deg,var(--brand) 0 6px,transparent 6px 13px);background-size:13px 2px;animation:flow .8s linear infinite;transition:opacity .3s}\n@keyframes flow{to{background-position:13px 0}}\n.node{display:flex;align-items:center;gap:10px;width:100%;text-align:left;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:9px 11px;transition:border-color .15s,background .15s,opacity .2s}\n.node:hover{border-color:var(--ink-3)}\n.node.sel{border-color:var(--brand);box-shadow:0 0 0 3px var(--brand-soft)}\n.node .t{flex:1;min-width:0}\n.node .t b{display:block;font-size:13.5px;font-weight:600;line-height:1.25}\n.node .t span{font-size:11.5px;color:var(--ink-3)}\n.core{background:var(--brand);color:var(--on-brand);border-radius:var(--r-lg);padding:14px;display:flex;flex-direction:column;gap:8px;flex:1;justify-content:center}\n.core .ttl{font-weight:600;font-size:15px;display:flex;align-items:center;gap:8px}\n.core .ttl{flex-wrap:wrap}\n.core .ttl-sub{flex-basis:100%;font-size:12px;font-weight:500;opacity:.8}\n.core .ttl i{width:9px;height:9px;border-radius:50%;background:var(--on-brand);animation:pulse 1.2s infinite}\n.core .node{background:rgba(255,255,255,.12);border-color:rgba(255,255,255,.22);color:var(--on-brand)}\n.core .node .t span{color:inherit;opacity:.75}\n.core .node.sel{box-shadow:0 0 0 3px rgba(255,255,255,.35);border-color:var(--on-brand)}\n.switch{position:relative;width:32px;height:18px;flex:none}\n.switch input{position:absolute;inset:0;opacity:0;margin:0;cursor:pointer}\n.switch span{position:absolute;inset:0;border-radius:999px;background:var(--line);transition:background .2s;pointer-events:none}\n.switch span::after{content:\"\";position:absolute;top:2px;left:2px;width:14px;height:14px;border-radius:50%;background:var(--card);box-shadow:0 1px 2px rgba(0,0,0,.25);transition:transform .2s}\n.switch input:checked+span{background:var(--good)}\n.switch input:checked+span::after{transform:translateX(14px)}\n.detail h3{font-size:17px}\n.detail .row{display:grid;grid-template-columns:120px minmax(0,1fr);gap:10px;padding-top:10px;margin-top:10px;border-top:1px solid var(--line-soft);font-size:13.5px}\n.detail .row b{font-size:12px;color:var(--ink-3);font-weight:600;text-transform:uppercase;letter-spacing:.04em;padding-top:1px}\n/* connect */\n.conn-head{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:24px;align-items:center;margin-bottom:18px}\n.conn-head .sec-head{margin-bottom:0}\n.beaver{margin:0;background:var(--card);border:1px solid var(--line);border-radius:var(--r-lg);padding:8px;box-shadow:var(--shadow);transform:rotate(1.5deg)}\n.beaver img{display:block;width:100%;height:auto;border-radius:8px}\n.beaver figcaption{font-size:11.5px;color:var(--ink-3);margin-top:6px;line-height:1.35}\n@media(max-width:700px){.conn-head{grid-template-columns:1fr}.beaver{max-width:320px;transform:none}}\n.conn{display:grid;grid-template-columns:270px minmax(0,1fr);gap:16px;align-items:start}\n.conn-list{padding:10px;display:flex;flex-direction:column;gap:2px}\n.conn-list h4{font-size:11.5px;text-transform:uppercase;letter-spacing:.06em;color:var(--ink-3);font-weight:600;margin:10px 8px 4px}\n.conn-list h4:first-child{margin-top:4px}\n.conn-list button{display:flex;justify-content:space-between;gap:8px;width:100%;text-align:left;border:0;background:transparent;border-radius:8px;padding:7px 9px;font-size:13.5px;color:var(--ink-2)}\n.conn-list button:hover{background:var(--sunk);color:var(--ink)}\n.conn-list button.on{background:var(--brand-soft);color:var(--brand-ink);font-weight:600}\n.conn-list button span{font-family:var(--mono);font-size:11px;color:var(--ink-3);white-space:nowrap;padding-top:2px}\n.conn-body h3{font-size:19px}\n.conn-body .meta{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}\n.conn-body h4{font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:var(--ink-3);font-weight:600;margin:18px 0 8px}\n.conn-body ol{margin:0;padding:0;list-style:none;counter-reset:c;display:flex;flex-direction:column;gap:8px}\n.conn-body ol li{counter-increment:c;display:grid;grid-template-columns:26px minmax(0,1fr);gap:10px;font-size:14px;line-height:1.5}\n.conn-body ol li::before{content:counter(c);display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:var(--brand-soft);color:var(--brand-ink);font-family:var(--mono);font-size:12px;font-weight:600}\n.conn-body code{font-family:var(--mono);font-size:12px;background:var(--sunk);border:1px solid var(--line-soft);padding:0 4px;border-radius:4px;overflow-wrap:anywhere}\n.conn-body .tip{margin-top:16px;padding:12px 14px;border-radius:var(--r);background:var(--warn-soft);color:var(--ink);font-size:13.5px}\n.conn-body .tip b{color:var(--warn)}\n.detail .go{margin-top:14px}\n@media(max-width:900px){\n  .conn{grid-template-columns:1fr}\n  .conn-list{flex-direction:row;flex-wrap:wrap;gap:6px}\n  .conn-list h4{width:100%;margin:6px 4px 0}\n  .conn-list button{width:auto;border:1px solid var(--line);border-radius:999px;padding:5px 11px;font-size:12.5px}\n  .conn-list button span{display:none}\n}\n@media(max-width:900px){\n  .map{grid-template-columns:1fr}\n  .pipes{flex-direction:row;justify-content:center;gap:28px;padding:4px 0;height:36px}\n  .pipe{width:2px;height:auto;margin:0;background:repeating-linear-gradient(180deg,var(--brand) 0 6px,transparent 6px 13px);background-size:2px 13px;animation:flowv .8s linear infinite}\n  .detail .row{grid-template-columns:1fr;gap:2px}\n}\n@keyframes flowv{to{background-position:0 13px}}\n\n/* parser */\n.parse{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}\n@media(max-width:900px){.parse{grid-template-columns:1fr}}\ntextarea{width:100%;min-height:96px;resize:vertical;border:1px solid var(--line);border-radius:var(--r);background:var(--sunk);padding:11px 12px;font-size:15px;line-height:1.45}\ntextarea:focus,input[type=text]:focus{outline:2px solid var(--brand);outline-offset:-1px}\n.hl{font-size:15px;line-height:1.7;padding:12px;border-radius:var(--r);background:var(--sunk);border:1px dashed var(--line);min-height:56px;overflow-wrap:anywhere}\nmark{border-radius:4px;padding:1px 3px;color:inherit}\nmark.m-who{background:var(--teal-soft);box-shadow:inset 0 -2px var(--teal)}\nmark.m-due{background:var(--warn-soft);box-shadow:inset 0 -2px var(--warn)}\nmark.m-pri{background:var(--bad-soft);box-shadow:inset 0 -2px var(--bad)}\nmark.m-proj{background:var(--alt-soft);box-shadow:inset 0 -2px var(--alt)}\nmark.m-act{background:var(--brand-soft);box-shadow:inset 0 -2px var(--brand)}\n.legend{display:flex;flex-wrap:wrap;gap:10px;font-size:12px;color:var(--ink-3);margin-top:8px}\n.legend span::before{content:\"\";display:inline-block;width:9px;height:9px;border-radius:2px;margin-right:5px;vertical-align:-1px;background:currentColor}\n.legend .l-who{color:var(--teal)} .legend .l-due{color:var(--warn)} .legend .l-pri{color:var(--bad)} .legend .l-proj{color:var(--alt)} .legend .l-act{color:var(--brand)}\n.result .verdict{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}\n.pill{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:600;padding:3px 10px;border-radius:999px}\n.pill.yes{background:var(--good-soft);color:var(--good)}\n.pill.no{background:var(--sunk);color:var(--ink-3);border:1px solid var(--line)}\n.fields{display:grid;gap:0}\n.field{display:grid;grid-template-columns:110px minmax(0,1fr);gap:10px;padding:9px 0;border-top:1px solid var(--line-soft);align-items:baseline;animation:fadeUp .35s ease both}\n.field:first-child{border-top:0}\n.field b{font-size:12px;color:var(--ink-3);font-weight:600}\n.field span{font-weight:500;overflow-wrap:anywhere}\n@keyframes fadeUp{from{opacity:0;transform:translateY(4px)}}\n.conf{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-3)}\n.conf .bar{width:80px;height:6px;border-radius:999px;background:var(--sunk);overflow:hidden;border:1px solid var(--line)}\n.conf .bar i{display:block;height:100%;background:var(--brand)}\n\n/* chat */\n.chat-wrap{display:grid;grid-template-columns:minmax(0,380px) minmax(0,1fr);gap:20px;align-items:start}\n@media(max-width:900px){.chat-wrap{grid-template-columns:1fr}}\n.phone{background:var(--chat);border:1px solid var(--line);border-radius:22px;overflow:hidden;box-shadow:var(--shadow-pop);max-width:420px;width:100%}\n.phone .bar{display:flex;align-items:center;gap:10px;background:var(--card);padding:10px 14px;border-bottom:1px solid var(--line)}\n.ava{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;font-weight:600;font-size:13px;flex:none;color:#fff}\n.ava.cat{background:var(--warn-soft);font-size:19px;line-height:1}\n.phone .bar b{display:block;font-size:14px;line-height:1.2}\n.phone .bar span{font-size:11.5px;color:var(--ink-3)}\n.msgs{height:470px;overflow-y:auto;padding:12px 10px 16px;display:flex;flex-direction:column;gap:6px;scroll-behavior:smooth}\n.msg{max-width:86%;background:var(--card);border-radius:12px 12px 12px 4px;padding:7px 10px 6px;font-size:13.5px;line-height:1.4;box-shadow:var(--shadow);animation:pop .25s ease both;align-self:flex-start;overflow-wrap:anywhere}\n.msg.out{align-self:flex-end;background:var(--out);border-radius:12px 12px 4px 12px}\n.msg .who{font-size:12px;font-weight:600;margin-bottom:2px}\n.msg .tm{float:right;font-size:10.5px;color:var(--ink-3);margin:6px 0 0 8px}\n.msg.bot{border:1px solid var(--brand-soft)}\n.msg.sys{align-self:center;background:var(--alt-soft);color:var(--alt);font-size:12.5px;border-radius:10px;max-width:94%;box-shadow:none}\n.divider{align-self:center;font-size:11.5px;background:rgba(0,0,0,.18);color:#fff;padding:2px 10px;border-radius:999px;margin:6px 0}\n.tcard{margin-top:6px;border:1px solid var(--line);border-radius:9px;padding:8px 10px;background:var(--sunk);font-size:12.5px}\n.tcard b{display:block;font-size:13px}\n.tcard .meta{display:flex;flex-wrap:wrap;gap:4px 10px;color:var(--ink-2);margin-top:3px}\n.ibtns{display:flex;gap:4px;margin-top:6px;flex-wrap:wrap}\n.ibtns button{flex:1;border:0;background:var(--brand-soft);color:var(--brand-ink);font-size:12.5px;font-weight:500;padding:6px 8px;border-radius:7px;min-width:90px}\n.ibtns button:hover{filter:brightness(.97)}\n.ibtns .done{font-size:12px;color:var(--good);font-weight:500}\n@keyframes pop{from{opacity:0;transform:translateY(6px) scale(.98)}}\n.typing{align-self:flex-start;background:var(--card);border-radius:12px;padding:9px 12px;display:flex;gap:4px}\n.typing i{width:6px;height:6px;border-radius:50%;background:var(--ink-3);animation:blink 1s infinite}\n.typing i:nth-child(2){animation-delay:.15s}.typing i:nth-child(3){animation-delay:.3s}\n@keyframes blink{50%{opacity:.2}}\n.voice{display:flex;align-items:center;gap:8px;min-width:200px}\n.voice .play{width:30px;height:30px;border-radius:50%;background:var(--brand);color:var(--on-brand);display:grid;place-items:center;font-size:11px;flex:none}\n.wave{display:flex;align-items:center;gap:2px;height:22px;flex:1}\n.wave i{width:3px;border-radius:2px;background:var(--ink-3)}\n.scn-side h3{font-size:18px}\n.scn-side p{color:var(--ink-2);margin-top:8px}\n.scn-side ul{margin:12px 0 0;padding-left:18px;color:var(--ink-2)}\n.scn-side li{margin-top:5px}\n.scn-ctrl{display:flex;gap:8px;align-items:center;margin-top:16px;flex-wrap:wrap}\n\n/* board */\n.board-top{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between;margin-bottom:12px}\n.tm{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:14px;align-items:center;padding:12px 16px;margin-bottom:12px}\n.tm .now b{display:block;font-family:var(--mono);font-size:18px;font-weight:600;white-space:nowrap}\n.tm .now span{font-size:11.5px;color:var(--ink-3)}\n.tm input[type=range]{width:100%;accent-color:var(--brand)}\n.tm .btns{display:flex;gap:6px}\n@media(max-width:700px){.tm{grid-template-columns:1fr}.tm .btns{flex-wrap:wrap}}\n.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:12px}\n.kpi{padding:12px 14px}\n.kpi span{font-size:12px;color:var(--ink-3)}\n.kpi b{display:block;font-family:var(--mono);font-size:24px;font-weight:600;letter-spacing:-.02em;margin-top:2px}\n.kpi.bad b{color:var(--bad)} .kpi.good b{color:var(--good)}\n@media(max-width:700px){.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}\n.board{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:14px;align-items:start}\n@media(max-width:1000px){.board{grid-template-columns:1fr}}\n.kanban{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}\n@media(max-width:700px){.kanban{grid-template-columns:1fr}}\n.kcol{background:var(--sunk);border:1px solid var(--line);border-radius:var(--r-lg);padding:10px;min-height:220px}\n.kcol h4{display:flex;justify-content:space-between;font-size:12.5px;color:var(--ink-2);font-weight:600;margin:2px 4px 10px}\n.kcol h4 span{font-family:var(--mono);color:var(--ink-3)}\n.kcards{display:flex;flex-direction:column;gap:8px}\n.tk{width:100%;text-align:left;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:9px 10px;transition:border-color .15s,transform .15s;animation:fadeUp .3s ease both}\n.tk:hover{border-color:var(--ink-3)}\n.tk.over{border-color:var(--bad);box-shadow:inset 3px 0 var(--bad)}\n.tk.fresh{box-shadow:0 0 0 3px var(--brand-soft);border-color:var(--brand)}\n.tk .tt{font-size:13px;font-weight:500;line-height:1.35}\n.tk .mt{display:flex;align-items:center;gap:6px;margin-top:7px;flex-wrap:wrap}\n.who-dot{display:inline-flex;align-items:center;gap:5px;font-size:11.5px;color:var(--ink-2)}\n.who-dot i{width:18px;height:18px;border-radius:50%;display:grid;place-items:center;font-style:normal;font-size:10px;font-weight:600;color:#fff}\n.due{font-family:var(--mono);font-size:11px;padding:1px 6px;border-radius:5px;background:var(--sunk);color:var(--ink-2);margin-left:auto;white-space:nowrap}\n.due.over{background:var(--bad-soft);color:var(--bad)}\n.due.today{background:var(--warn-soft);color:var(--warn)}\n.due.ok{background:var(--good-soft);color:var(--good)}\n.feed{display:flex;flex-direction:column;max-height:620px}\n.feed .fh{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border-bottom:1px solid var(--line)}\n.feed .fh b{font-size:14px}\n.feed .fl{overflow-y:auto;padding:8px;display:flex;flex-direction:column;gap:6px}\n.ev{border:1px solid var(--line-soft);background:var(--sunk);border-radius:9px;padding:8px 10px;font-size:12.5px;line-height:1.4}\n.ev.new{animation:flash 1.2s ease}\n@keyframes flash{0%{background:var(--brand-soft);border-color:var(--brand)}}\n.ev .eh{display:flex;justify-content:space-between;gap:8px;font-size:11px;color:var(--ink-3);margin-bottom:3px}\n.ev .eh b{color:var(--ink-2);font-weight:600}\n.ev.k-esc{border-color:var(--bad);background:var(--bad-soft)}\n.ev.k-brief{border-color:var(--brand);background:var(--brand-soft)}\n.ev.k-done{border-color:transparent;background:var(--good-soft)}\n.ev.k-chat{border-color:var(--warn);background:var(--warn-soft)}\n.empty{color:var(--ink-3);font-size:13px;padding:14px;text-align:center}\n.qadd{display:flex;gap:8px;margin-top:12px}\n.qadd input{flex:1;min-width:0;border:1px solid var(--line);border-radius:var(--r);background:var(--card);padding:9px 12px}\n\n/* reminders */\n.ladder-ctrl{display:flex;flex-wrap:wrap;gap:18px;align-items:center;margin-bottom:16px}\n.ladder-ctrl label.tg{display:flex;align-items:center;gap:8px;font-size:13.5px;color:var(--ink-2)}\n.ladder{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}\n@media(max-width:800px){.ladder{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media(max-width:480px){.ladder{grid-template-columns:1fr}}\n.step{position:relative;padding:14px;border-radius:var(--r-lg);background:var(--card);border:1px solid var(--line);transition:opacity .2s}\n.step.off{opacity:.38}\n.step .when{font-family:var(--mono);font-size:12px;font-weight:600;color:var(--brand)}\n.step .to{font-size:11.5px;color:var(--ink-3);margin-top:2px}\n.step .bubble{margin-top:10px;font-size:13px;background:var(--sunk);border-radius:10px 10px 10px 3px;padding:8px 10px;line-height:1.4}\n.step.esc .when{color:var(--bad)}\n.step.chat .when{color:var(--warn)}\n\n/* memory */\n.mem{position:relative;display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:56px;align-items:start}\n.mem .links{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:2;overflow:visible}\n.mem .links path{fill:none;stroke:var(--brand);stroke-width:2;stroke-dasharray:6 5;animation:dash 1s linear infinite}\n.mem .links path.hint{stroke:var(--ink-3);stroke-width:1.5}\n.mem .links circle{fill:var(--brand)}\n.mem .links circle.hint{fill:var(--ink-3)}\n@keyframes dash{to{stroke-dashoffset:-11}}\n.fact .fto{display:inline-block;margin-top:6px;font-size:11.5px;font-weight:600;color:var(--brand)}\n.kv .src-from,.person .src-from{display:block;font-size:11.5px;color:var(--brand);margin-top:3px}\n.tabs button.hint{box-shadow:0 0 0 2px var(--brand)}\n@media(max-width:900px){.mem{grid-template-columns:1fr;gap:16px}.mem .links{display:none}}\n.facts{display:flex;flex-direction:column;gap:8px}\n.fact{display:block;width:100%;text-align:left;border:1px solid var(--line);background:var(--card);border-radius:10px;padding:10px 12px}\n.fact:hover{border-color:var(--brand)}\n.fact .ff{font-size:11.5px;color:var(--ink-3)}\n.fact .fx{font-size:13.5px;margin-top:2px}\n.fact.used{opacity:.5;border-style:dashed}\n.fact.used .fto{color:var(--good)}\n.kb .kbh{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 14px;border-bottom:1px solid var(--line)}\n.kb .kbb{padding:6px 16px 14px}\n.kv{display:grid;grid-template-columns:150px minmax(0,1fr);gap:10px;padding:9px 0;border-top:1px solid var(--line-soft);font-size:13.5px}\n.kv:first-child{border-top:0}\n.kv b{color:var(--ink-3);font-weight:500;font-size:12.5px}\n.kv.flash{animation:flash 1.6s ease;border-radius:6px}\n.kv .nil{color:var(--ink-3)}\n@media(max-width:560px){.kv{grid-template-columns:1fr;gap:2px}}\n.person{display:grid;grid-template-columns:36px minmax(0,1fr);gap:10px;padding:10px 0;border-top:1px solid var(--line-soft)}\n.person:first-child{border-top:0}\n.person .pn{font-weight:600;font-size:13.5px}\n.person .pr{font-size:12.5px;color:var(--ink-2)}\n.person .tags{display:flex;flex-wrap:wrap;gap:4px;margin-top:5px}\n.tag{font-size:11px;padding:1px 7px;border-radius:999px;background:var(--sunk);border:1px solid var(--line);color:var(--ink-2)}\n.tag.w{background:var(--warn-soft);border-color:transparent;color:var(--warn)}\n.tag.g{background:var(--good-soft);border-color:transparent;color:var(--good)}\n.person.flash{animation:flash 1.6s ease;border-radius:8px}\npre.file{margin:0;font-family:var(--mono);font-size:12px;line-height:1.55;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--ink-2);max-height:440px;overflow:auto}\n.impact{margin-top:12px;padding:12px 14px;border-radius:var(--r);background:var(--brand-soft);color:var(--brand-ink);font-size:13.5px}\n.impact b{display:block;font-size:11.5px;text-transform:uppercase;letter-spacing:.05em;margin-bottom:3px}\n\n/* ask */\n.ask{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:16px;align-items:start}\n@media(max-width:900px){.ask{grid-template-columns:1fr}}\n.qs{display:flex;flex-direction:column;gap:6px}\n.qs .chip{border-radius:10px;padding:9px 12px;font-size:13.5px}\n.answer{min-height:360px;display:flex;flex-direction:column}\n.answer .ah{display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line)}\n.answer .ab{padding:14px 18px;font-size:14px;line-height:1.55;flex:1}\n.answer .ab > *{animation:fadeUp .3s ease both}\n.answer .ab h4{font-size:14px;margin:12px 0 4px}\n.answer .ab h4:first-child{margin-top:0}\n.answer .ab ul{margin:4px 0;padding-left:18px}\n.answer .ab li{margin:3px 0}\n.answer .ab .q{font-size:12.5px;color:var(--ink-3);margin-bottom:10px}\n.ask-in{display:flex;gap:8px;padding:12px 14px;border-top:1px solid var(--line)}\n.ask-in input{flex:1;min-width:0;border:1px solid var(--line);border-radius:var(--r);background:var(--sunk);padding:9px 12px}\n\n/* triggers */\n.rules{display:flex;flex-direction:column;gap:10px}\n.rule{display:grid;grid-template-columns:minmax(0,1.2fr) 130px minmax(0,1.2fr) auto;gap:16px;align-items:center;padding:14px 16px}\n.rule .if b,.rule .then b{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--ink-3);margin-bottom:2px}\n.rule .if{font-size:13.5px}\n.rule .then{font-size:13.5px}\n.rule svg{width:130px;height:40px;display:block;overflow:visible}\n.rule.fired{border-color:var(--good)}\n.rule .res{grid-column:1/-1;font-size:12.5px;color:var(--good);margin-top:-6px}\n@media(max-width:800px){.rule{grid-template-columns:1fr;gap:8px}}\n\n/* ideas */\n.ideas{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:10px}\n.idea{display:flex;flex-direction:column;gap:6px;text-align:left;padding:14px;border-radius:var(--r-lg);background:var(--card);border:1px solid var(--line);transition:border-color .15s,box-shadow .15s}\n.idea:hover{border-color:var(--ink-3)}\n.idea.on{border-color:var(--brand);box-shadow:0 0 0 3px var(--brand-soft)}\n.idea h3{font-size:14.5px}\n.idea p{font-size:13px;color:var(--ink-2);flex:1}\n.idea .im{display:flex;justify-content:space-between;align-items:center;font-size:11.5px;color:var(--ink-3);margin-top:4px}\n.dots{letter-spacing:2px;font-family:var(--mono)}\n.idea .add{font-weight:600;color:var(--brand)}\n.idea.on .add{color:var(--good)}\n\n/* builder */\n.build{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:16px;align-items:start}\n@media(max-width:900px){.build{grid-template-columns:1fr}}\n.mods h4{font-size:11.5px;text-transform:uppercase;letter-spacing:.06em;color:var(--ink-3);margin:14px 0 6px}\n.mods h4:first-child{margin-top:0}\n.mod{display:flex;align-items:center;gap:10px;padding:7px 0;font-size:13.5px;cursor:pointer}\n.mod input{width:16px;height:16px;accent-color:var(--brand);flex:none}\n.mod .d{margin-left:auto;font-family:var(--mono);font-size:11.5px;color:var(--ink-3);white-space:nowrap}\n.out .sum{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-bottom:14px}\n.out .sum div{background:var(--sunk);border:1px solid var(--line-soft);border-radius:var(--r);padding:10px 12px}\n.out .sum span{font-size:11.5px;color:var(--ink-3)}\n.out .sum b{display:block;font-family:var(--mono);font-size:20px;font-weight:600}\n.phase{padding:10px 0;border-top:1px solid var(--line-soft)}\n.phase b{font-size:13px}\n.phase p{font-size:13px;color:var(--ink-2);margin-top:2px}\n.need{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}\n.accs{display:flex;flex-direction:column;gap:6px;margin-top:8px}\n.acc{border:1px solid var(--line);border-radius:var(--r);background:var(--card)}\n.acc summary{cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:10px;padding:9px 12px;font-size:13.5px;font-weight:500}\n.acc summary::-webkit-details-marker{display:none}\n.acc summary::after{content:\"+\";font-family:var(--mono);color:var(--ink-3);font-size:15px}\n.acc[open] summary::after{content:\"−\"}\n.acc[open]{border-color:var(--brand)}\n.acc[open] summary{color:var(--brand-ink)}\n.acc ol{margin:0;padding:2px 14px 12px 32px;font-size:13px;color:var(--ink-2);display:flex;flex-direction:column;gap:5px}\n.acc code{font-family:var(--mono);font-size:11.5px;background:var(--sunk);border:1px solid var(--line-soft);padding:0 4px;border-radius:4px;overflow-wrap:anywhere}\n.acc b{color:var(--ink)}\n.acc.plain{padding:9px 12px;font-size:13.5px}\n.prompt{margin-top:14px;background:var(--sunk);border:1px solid var(--line);border-radius:var(--r);padding:12px}\n.prompt .ph{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;font-size:12.5px;color:var(--ink-3);font-weight:600}\n\n.toast{position:fixed;left:50%;bottom:calc(20px + env(safe-area-inset-bottom,0px));transform:translateX(-50%) translateY(20px);background:var(--ink);color:var(--bg);padding:10px 16px;border-radius:10px;font-size:13.5px;box-shadow:var(--shadow-pop);opacity:0;pointer-events:none;transition:opacity .25s,transform .25s;z-index:50;max-width:calc(100% - 32px)}\n.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}\n.toast a{color:inherit;font-weight:600}\n/* cats */\n.cat-dock{position:fixed;bottom:calc(16px + env(safe-area-inset-bottom,0px));z-index:40;display:flex;align-items:flex-end;gap:6px;animation:catIn .7s cubic-bezier(.3,1.6,.5,1) both}\n.cat-dock.right{right:16px} .cat-dock.left{left:16px;flex-direction:row-reverse}\n.cat-dock.out{animation:catOut .45s ease-in both}\n@keyframes catIn{from{transform:translateY(140%) rotate(-8deg)}}\n@keyframes catOut{to{transform:translateY(140%) rotate(8deg)}}\n.cat-peek{width:96px;height:96px;padding:0;border:3px solid #2B2B33;border-radius:50%;background:#FFF4DE;box-shadow:0 8px 24px rgba(16,24,40,.25);overflow:hidden;animation:catBob 2.4s ease-in-out infinite}\n.cat-peek:hover{transform:scale(1.06)}\n.cat-peek svg{width:100%;height:100%;display:block}\n@keyframes catBob{50%{transform:translateY(-5px) rotate(-3deg)}}\n.cat-say{max-width:190px;background:#FFFFFF;color:#2B2B33;border:3px solid #2B2B33;border-radius:16px 16px 16px 4px;padding:8px 11px;font-size:13px;font-weight:600;line-height:1.3;margin-bottom:58px;box-shadow:0 6px 18px rgba(16,24,40,.18)}\n.cat-dock.left .cat-say{border-radius:16px 16px 4px 16px}\n.cat-x{position:absolute;top:-6px;width:24px;height:24px;border-radius:50%;border:2px solid #2B2B33;background:#FFFFFF;color:#2B2B33;font-size:14px;line-height:1;padding:0}\n.cat-dock.right .cat-x{right:-4px} .cat-dock.left .cat-x{left:-4px}\n.cat-modal{position:fixed;inset:0;z-index:60;background:rgba(16,24,40,.55);display:grid;place-items:center;padding:16px;animation:fadeIn .2s ease both}\n@keyframes fadeIn{from{opacity:0}}\n.cat-card{position:relative;width:min(380px,100%);background:#FFF4DE;color:#2B2B33;border:4px solid #2B2B33;border-radius:28px;padding:22px 22px 18px;text-align:center;box-shadow:0 30px 70px rgba(0,0,0,.35);animation:catPop .5s cubic-bezier(.3,1.6,.5,1) both}\n@keyframes catPop{from{transform:scale(.4) rotate(-10deg);opacity:0}}\n.cat-card svg{width:min(260px,70vw);height:auto;display:block;margin:0 auto}\n.cat-card h3{font-size:20px;margin-top:6px;color:#2B2B33}\n.cat-card p{font-size:14.5px;margin-top:6px;color:#4A4A55}\n.cat-card .row{display:flex;gap:8px;justify-content:center;margin-top:16px;flex-wrap:wrap}\n.cat-card button{border:3px solid #2B2B33;border-radius:999px;padding:7px 16px;font-weight:700;font-size:14px;background:#FFFFFF;color:#2B2B33}\n.cat-card button.go{background:#FFB84D}\n.cat-card .close{position:absolute;top:10px;right:12px;width:32px;height:32px;padding:0;font-size:18px}\n.cat-tail{transform-origin:150px 160px;animation:tail 1.6s ease-in-out infinite}\n@keyframes tail{50%{transform:rotate(12deg)}}\n.cat-blink{transform-origin:center;animation:blink2 4s infinite}\n@keyframes blink2{0%,92%,100%{transform:scaleY(1)}95%{transform:scaleY(.1)}}\n@media (prefers-reduced-motion: reduce){.cat-peek,.cat-tail,.cat-blink{animation:none}}\n@media (prefers-reduced-motion: reduce){\n  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}\n}\n</style>\n</head>\n<body>\n\n<main class=\"wrap\">\n\n<!-- MAP -->\n<section id=\"map\">\n  <div class=\"sec-head\">\n    <h2>Всё стекается в одну OS, а оттуда расходится по людям</h2>\n    <p>Нажмите на любой блок, чтобы увидеть, что он делает. Пошаговая инструкция по подключению каждого блока ниже, в разделе «Как подключить».</p>\n  </div>\n  <div class=\"card pad\">\n    <div class=\"map\">\n      <div class=\"col\" id=\"mapSources\"><h4>Откуда приходят задачи</h4></div>\n      <div class=\"pipes\" id=\"pipesL\"></div>\n      <div class=\"col\"><h4>OS</h4><div class=\"core\" id=\"mapCore\"><div class=\"ttl\"><i></i>🐱 ИИ-котёнок<span class=\"ttl-sub\">мурчит над задачами, ничего не теряет</span></div></div></div>\n      <div class=\"pipes\" id=\"pipesR\"></div>\n      <div class=\"col\" id=\"mapOutputs\"><h4>Что получаете</h4></div>\n    </div>\n  </div>\n  <div class=\"card pad detail\" id=\"mapDetail\" style=\"margin-top:16px\"></div>\n</section>\n\n<!-- CONNECT -->\n<section id=\"connect\">\n  <div class=\"conn-head\">\n    <div class=\"sec-head\">\n      <h2>Как подключить каждый блок</h2>\n      <p>Выберите блок слева: что понадобится, шаги по порядку и на чём обычно спотыкаются. Время указано для сборки вместе с Claude Code.</p>\n    </div>\n    <figure class=\"beaver\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Бобр на берегу ручья\" width=\"640\" height=\"425\">\n      <figcaption>Бобр-инженер: строит связки так же надёжно, как плотины. Фото: GlacierNPS, общественное достояние</figcaption>\n    </figure>\n  </div>\n  <div class=\"conn\">\n    <div class=\"card conn-list\" id=\"connList\"></div>\n    <div class=\"card pad conn-body\" id=\"connBody\"></div>\n  </div>\n</section>\n\n<!-- PARSER -->\n<section id=\"parse\">\n  <div class=\"sec-head\">\n    <h2>Пишете как обычно, ассистент вытаскивает кто, что и когда</h2>\n    <p>Выберите пример или напишите своё сообщение, как в рабочем чате. Ассистент решит, задача это или просто болтовня, и разложит её на поля.</p>\n  </div>\n  <div class=\"parse\">\n    <div class=\"card pad\">\n      <label for=\"parseIn\" class=\"small muted\">Сообщение из чата</label>\n      <textarea id=\"parseIn\" style=\"margin-top:6px\" spellcheck=\"false\">Маша, запусти до четверга ретаргет на тех, кто дошёл до корзины</textarea>\n      <div class=\"chips\" id=\"parseSamples\" style=\"margin-top:10px\"></div>\n      <div style=\"margin-top:16px\" class=\"small muted\">Что увидел ассистент</div>\n      <div class=\"hl\" id=\"parseHl\" style=\"margin-top:6px\"></div>\n      <div class=\"legend\"><span class=\"l-act\">действие</span><span class=\"l-who\">исполнитель</span><span class=\"l-due\">срок</span><span class=\"l-pri\">приоритет</span><span class=\"l-proj\">проект</span></div>\n    </div>\n    <div class=\"card pad result\">\n      <div class=\"verdict\"><span id=\"parseVerdict\"></span><span class=\"conf\" id=\"parseConf\"></span></div>\n      <div class=\"fields\" id=\"parseFields\"></div>\n      <div style=\"display:flex;gap:8px;margin-top:14px;flex-wrap:wrap\">\n        <button class=\"btn primary\" id=\"parseAdd\">Добавить на доску</button>\n        <a class=\"btn\" href=\"#board\">Открыть доску</a>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- CHATS -->\n<section id=\"chats\">\n  <div class=\"sec-head\">\n    <h2>Пять сцен из жизни ассистента</h2>\n    <p>Нажмите «Запустить» и посмотрите, как это выглядит в Telegram. Кнопки в карточках задач кликабельны.</p>\n  </div>\n  <div class=\"tabs\" id=\"scnTabs\" role=\"tablist\" style=\"margin-bottom:14px\"></div>\n  <div class=\"chat-wrap\">\n    <div class=\"phone\">\n      <div class=\"bar\"><div class=\"ava\" id=\"scnAva\">М</div><div><b id=\"scnTitle\">Маркетинг</b><span id=\"scnSub\">5 участников, ассистент</span></div></div>\n      <div class=\"msgs\" id=\"msgs\"></div>\n    </div>\n    <div class=\"card pad scn-side\" id=\"scnSide\"></div>\n  </div>\n</section>\n\n<!-- BOARD -->\n<section id=\"board\">\n  <div class=\"sec-head\">\n    <h2>Все задачи команды в одном месте, со сроками и источником</h2>\n    <p>Двигайте время ползунком или нажмите «Пустить время». Исполнители что-то закрывают вовремя, что-то срывают, а ассистент шлёт напоминания и эскалации в ленту справа. Клик по карточке меняет статус.</p>\n  </div>\n  <div class=\"card tm\">\n    <div class=\"now\"><span>Сейчас в демо</span><b id=\"tmNow\">пн 10:00</b></div>\n    <div><label for=\"tmRange\" class=\"small muted\" id=\"tmLabel\">прошло 0 ч</label><input type=\"range\" id=\"tmRange\" min=\"0\" max=\"168\" step=\"1\" value=\"0\"></div>\n    <div class=\"btns\"><button class=\"btn primary sm\" id=\"tmPlay\">Пустить время</button><button class=\"btn sm\" id=\"tmDay\">+1 день</button><button class=\"btn sm\" id=\"tmReset\">Сбросить</button></div>\n  </div>\n  <div class=\"kpis\">\n    <div class=\"card kpi\"><span>Открыто</span><b id=\"kOpen\">0</b></div>\n    <div class=\"card kpi bad\"><span>Просрочено</span><b id=\"kOver\">0</b></div>\n    <div class=\"card kpi\"><span>Срок сегодня</span><b id=\"kToday\">0</b></div>\n    <div class=\"card kpi good\"><span>Закрыто в срок</span><b id=\"kOnTime\">—</b></div>\n  </div>\n  <div class=\"board-top\">\n    <div class=\"chips\" id=\"whoFilter\"></div>\n    <div class=\"chips\"><button class=\"chip\" id=\"chaos\">Устроить понедельник</button><button class=\"chip\" id=\"onlyOver\">Только просроченные</button></div>\n  </div>\n  <div class=\"board\">\n    <div>\n      <div class=\"kanban\" id=\"kanban\"></div>\n      <form class=\"qadd\" id=\"qadd\"><input type=\"text\" id=\"qaddIn\" placeholder=\"Напишите задачу как в чате: «Аня, пост про акцию к пятнице»\" autocomplete=\"off\"><button class=\"btn primary\" type=\"submit\">Добавить</button></form>\n    </div>\n    <div class=\"card feed\">\n      <div class=\"fh\"><b>Что отправил ассистент</b><span class=\"mono small muted\" id=\"feedCount\">0</span></div>\n      <div class=\"fl\" id=\"feed\"></div>\n    </div>\n  </div>\n</section>\n\n<!-- REMIND -->\n<section id=\"remind\">\n  <div class=\"sec-head\">\n    <h2>Кому, когда и каким тоном напоминать</h2>\n    <p>Настройки сразу влияют на ленту в доске выше. Попробуйте режим «жёстко» и включите публичный пинг в общий чат.</p>\n  </div>\n  <div class=\"card pad\">\n    <div class=\"ladder-ctrl\">\n      <div class=\"tabs\" id=\"toneTabs\"></div>\n      <label class=\"tg\"><span class=\"switch\"><input type=\"checkbox\" id=\"optQuiet\" checked><span></span></span>Тихие часы 21:00–9:00</label>\n      <label class=\"tg\"><span class=\"switch\"><input type=\"checkbox\" id=\"optEsc\" checked><span></span></span>Эскалация руководителю</label>\n      <label class=\"tg\"><span class=\"switch\"><input type=\"checkbox\" id=\"optChat\"><span></span></span>Пинг в общий чат через сутки</label>\n    </div>\n    <div class=\"ladder\" id=\"ladder\"></div>\n  </div>\n</section>\n\n<!-- MEMORY -->\n<section id=\"memory\">\n  <div class=\"sec-head\">\n    <h2>Ассистент запоминает факты о вас, проекте и команде</h2>\n    <p>Из переписки он вытаскивает не только задачи, но и знания: кто в отпуске, какой бюджет согласовали, как вы любите получать отчёты. Нажимайте на факты слева: линия покажет, в какое поле памяти записался факт, а ниже появится, что изменится в поведении ассистента.</p>\n  </div>\n  <div class=\"mem\" id=\"mem\">\n    <svg class=\"links\" id=\"memLinks\" aria-hidden=\"true\"></svg>\n    <div>\n      <div class=\"facts\" id=\"facts\"></div>\n      <div class=\"impact\" id=\"impact\" hidden></div>\n    </div>\n    <div class=\"card kb\">\n      <div class=\"kbh\"><div class=\"tabs\" id=\"kbTabs\"></div><button class=\"btn sm\" id=\"kbFile\">Показать как файл скилла</button></div>\n      <div class=\"kbb\" id=\"kbBody\"></div>\n    </div>\n  </div>\n</section>\n\n<!-- ASK -->\n<section id=\"ask\">\n  <div class=\"sec-head\">\n    <h2>Спросите что угодно о работе</h2>\n    <p>Ответы считаются по живой доске выше: подвиньте время, закройте пару задач и спросите снова.</p>\n  </div>\n  <div class=\"ask\">\n    <div class=\"qs\" id=\"qs\"></div>\n    <div class=\"card answer\">\n      <div class=\"ah\"><div class=\"ava cat\" aria-label=\"Ассистент\">🐱</div><div><b style=\"font-size:14px\">Ассистент</b><div class=\"small muted\" id=\"askCtx\">видит 0 задач, 5 человек, 7 источников</div></div></div>\n      <div class=\"ab\" id=\"askOut\"><p class=\"muted\">Выберите вопрос слева или задайте свой.</p></div>\n      <form class=\"ask-in\" id=\"askForm\"><input type=\"text\" id=\"askIn\" placeholder=\"Например: кто сейчас самый загруженный?\" autocomplete=\"off\"><button class=\"btn primary\" type=\"submit\">Спросить</button></form>\n    </div>\n  </div>\n</section>\n\n<!-- TRIGGERS -->\n<section id=\"triggers\">\n  <div class=\"sec-head\">\n    <h2>Цифры сами создают задачи</h2>\n    <p>Ассистент читает <a href=\"https://cmo-razbory.oxion-ezhkov.workers.dev/dashboard\" target=\"_blank\" rel=\"noopener\">дашборд с прошлого воркшопа</a> и CRM. Когда метрика уходит за порог, задача появляется у ответственного без вашего участия. Нажмите «Попробовать»: метрика уйдёт за порог, и задача появится на доске.</p>\n  </div>\n  <div class=\"rules\" id=\"rules\"></div>\n</section>\n\n<!-- IDEAS -->\n<section id=\"ideas\">\n  <div class=\"sec-head\">\n    <h2>Идеи сверху: выберите, что хотите себе</h2>\n    <p>Отмеченные идеи попадут в конструктор ниже и в промпт для сборки.</p>\n  </div>\n  <div class=\"ideas\" id=\"ideaGrid\"></div>\n</section>\n\n<!-- BUILD -->\n<section id=\"build\">\n  <div class=\"sec-head\">\n    <h2>Соберите свою систему и заберите промпт</h2>\n    <p>Отметьте модули. Справа появится план сборки по этапам, список доступов и готовый промпт для Claude Code.</p>\n  </div>\n  <div class=\"build\">\n    <div class=\"card pad mods\" id=\"mods\"></div>\n    <div class=\"card pad out\" id=\"buildOut\"></div>\n  </div>\n</section>\n\n</main>\n<div style=\"height:64px\"></div>\n\n<div class=\"cat-dock right\" id=\"catDock\" hidden>\n  <div class=\"cat-say\" id=\"catSay\"></div>\n  <div style=\"position:relative\"><button class=\"cat-peek\" id=\"catPeek\" aria-label=\"Развернуть котика\"></button><button class=\"cat-x\" id=\"catX\" aria-label=\"Спрятать котика\">×</button></div>\n</div>\n<div class=\"cat-modal\" id=\"catModal\" hidden>\n  <div class=\"cat-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"catTitle\">\n    <button class=\"close\" id=\"catClose\" aria-label=\"Закрыть\">×</button>\n    <div id=\"catBig\"></div>\n    <h3 id=\"catTitle\"></h3>\n    <p id=\"catText\"></p>\n    <div class=\"row\"><button class=\"go\" id=\"catMore\">Ещё котика</button><button id=\"catOk\">Мур, понял</button></div>\n  </div>\n</div>\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n<script>\n(function(){\n\"use strict\";\nvar $ = function(s, r){ return (r||document).querySelector(s); };\nvar $$ = function(s, r){ return Array.prototype.slice.call((r||document).querySelectorAll(s)); };\nfunction esc(s){ return String(s).replace(/[&<>\"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]; }); }\nfunction pad(n){ return (n<10?'0':'')+n; }\nvar reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\nfunction sleep(ms){ return new Promise(function(r){ setTimeout(r, ms); }); }\nvar toastT;\nfunction toast(html){ var t=$('#toast'); t.innerHTML=html; t.classList.add('show'); clearTimeout(toastT); toastT=setTimeout(function(){ t.classList.remove('show'); }, 3200); }\n\n/* ───────── Команда, источники, время ───────── */\nvar TEAM = {\n  me:     {name:'Вы',    role:'Руководитель маркетинга', color:'#2B4ACB'},\n  masha:  {name:'Маша',  role:'Таргетолог',             color:'#0E7C86'},\n  dima:   {name:'Дима',  role:'Дизайнер',               color:'#B7791F'},\n  anya:   {name:'Аня',   role:'SMM',                    color:'#5B4BD6'},\n  kostya: {name:'Костя', role:'Продажи',                color:'#C4373C'}\n};\nvar TEAM_IDS = ['me','masha','dima','anya','kostya'];\nvar SRC = {\n  tg:{label:'ЧАТ', full:'Рабочий чат'}, biz:{label:'ЛИЧКА', full:'Личка (Business-бот)'}, mail:{label:'ПОЧТА', full:'Почта'},\n  cal:{label:'КАЛЕНДАРЬ', full:'Календарь'}, crm:{label:'CRM', full:'CRM'}, dash:{label:'ДАШБОРД', full:'Дашборд маркетинга'},\n  voice:{label:'ГОЛОС', full:'Голосовое или созвон'}, web:{label:'ВРУЧНУЮ', full:'Добавлено вручную'}\n};\nfunction srcBadge(s){ var k = s==='web' ? '' : 's-'+s; return '<span class=\"src '+k+'\">'+SRC[s].label+'</span>'; }\nfunction whoDot(id){ var p=TEAM[id]; return '<span class=\"who-dot\"><i style=\"background:'+p.color+'\">'+esc(p.name[0])+'</i>'+esc(p.name)+'</span>'; }\n\nvar DAYS = ['вс','пн','вт','ср','чт','пт','сб'];\nvar DAYS_FULL = ['воскресенье','понедельник','вторник','среда','четверг','пятница','суббота'];\nvar BASE = (function(){ var d=new Date(); d.setHours(10,0,0,0); return d; })();\nfunction at(h){ return new Date(BASE.getTime()+h*3600e3); }\nfunction clock(h){ var d=at(h); return pad(d.getHours())+':'+pad(d.getMinutes()); }\nfunction fmt(h){ var d=at(h); return DAYS[d.getDay()]+', '+pad(d.getDate())+'.'+pad(d.getMonth()+1)+' '+clock(h); }\nfunction dayIdx(h){ return Math.floor((h+10)/24); }\nfunction D(day, hour){ return day*24 + hour - 10; }\nfunction dowOf(day){ return at(D(day,12)).getDay(); }\nfunction hrs(n){ n=Math.round(n); if(n<24) return n+' ч'; var d=Math.round(n/24); return d+' '+plural(d,'день','дня','дней'); }\nfunction plural(n,a,b,c){ n=Math.abs(n)%100; var n1=n%10; if(n>10&&n<20) return c; if(n1>1&&n1<5) return b; if(n1===1) return a; return c; }\nfunction relDue(due, h){\n  var diff = due - h;\n  if (diff < 0) return {t:fmt(due), c:'over'};\n  return {t:fmt(due), c: dayIdx(due)===dayIdx(h) ? 'today' : ''};\n}\n\n/* ───────── 1. Схема ───────── */\nvar NODES = {\n  tg:{side:'src', w:30, t:'Бот в рабочих чатах', s:'Telegram-группы команды, текст и голосовые', what:'Сидит во всех рабочих чатах, читает переписку и расшифровывает голосовые. Замечает договорённости: «Маша, сделай к четвергу». Присылает карточку задачи с кнопками «Принять» и «Другой срок».', how:'Бот из BotFather, добавлен в группы, privacy mode выключен. Вебхук на воркер, голосовые идут в расшифровку.', ex:'«Дима, баннер к 15:00» → задача Диме, срок сегодня 15:00, приоритет высокий.'},\n  biz:{side:'src', w:20, t:'ТГ Business-бот в личке', s:'Ваши переписки в Telegram, текст и голосовые', what:'Видит вашу личку с клиентами и подрядчиками, голосовые тоже расшифровывает. Ловит запросы («пришлите КП») и ваши обещания («скину завтра»), ставит задачи вам, обновляет карточку клиента.', how:'Telegram Premium → Telegram для бизнеса → Чат-боты. Выбираете, какие чаты видит бот.', ex:'Клиент: «Пришлите кейсы до пятницы». Вы: «Конечно». → вам задача на пт 12:00.'},\n  mail:{side:'src', w:15, t:'Почта', s:'Gmail, Яндекс', what:'Читает входящие, находит письма с просьбами и дедлайнами: акты, согласования, запросы клиентов. Рассылки и уведомления пропускает.', how:'Gmail API через OAuth или пересылка писем на адрес воркера.', ex:'«Подпишите акты до 25-го» → задача вам на 25-е, проект «Финансы».'},\n  cal:{side:'src', w:10, t:'Календарь', s:'Встречи и созвоны', what:'Знает, когда вы заняты. Перед встречей присылает справку: кто это, какие открыты задачи, о чём договаривались. Не ставит дедлайны на время встреч.', how:'Google Calendar API, чтение событий и свободных слотов.', ex:'За 15 минут до встречи с «Кадром»: «2 открытые задачи, последний разговор был про сценарий».'},\n  crm:{side:'src', w:15, t:'CRM', s:'amoCRM, Bitrix24 и др.', what:'Следит за сделками: лид без ответа, сделка без движения, обещанный созвон. Создаёт задачи менеджерам и видит, по какому клиенту что открыто.', how:'Вебхуки CRM на воркер плюс API для чтения сделок.', ex:'Сделка 7 дней без движения → Косте задача «связаться», срок сегодня.'},\n  voice:{side:'src', w:5, t:'Созвоны в Zoom', s:'Записи и транскрипты встреч', what:'После созвона забирает транскрипт из Zoom, собирает итоги и решения и раскладывает договорённости по исполнителям.', how:'Записи и транскрипты Zoom через его API → тот же разбор в Claude.', ex:'Планёрка на 40 минут → протокол и 5 задач трём людям с разными сроками.'},\n  dash:{side:'src', w:5, t:'Дашборд маркетинга', s:'Метрики с прошлого воркшопа', what:'Смотрит на цифры: CPL, конверсии, расход. Когда метрика уходит за порог, ставит задачу ответственному и пишет вам почему.', how:'Тот же воркер читает data.json дашборда, правила задаются в настройках.', ex:'CPL в Директе +38% за 3 дня → Маше «проверить кампании», срок сегодня 18:00.'},\n  parse:{side:'core', t:'Разбор в задачи', s:'Кто, что, когда, приоритет', what:'Каждое сообщение проходит через Claude: задача это или нет, кто исполнитель, какой срок, к какому проекту относится. Если не уверен, уточняет.', how:'Claude API получает вместе с сообщением команду, проекты и выдержку из базы знаний.', ex:'«Скину завтра утром» → обещание, исполнитель вы, срок завтра 11:00.'},\n  dl:{side:'core', t:'Сроки и напоминания', s:'Cron каждые 15 минут', what:'Помнит все сроки. Пишет исполнителю заранее, в день срока и после просрочки, эскалирует руководителю. Уважает тихие часы.', how:'Cron-триггер воркера, лестница напоминаний в настройках.', ex:'За сутки, за 2 часа, через час после срока, через 4 часа руководителю.'},\n  kb:{side:'core', t:'База знаний', s:'Скилл о вас, проекте, команде', what:'Копит факты из переписки: отпуска, бюджеты, договорённости, предпочтения. Это контекст для всех ответов и решений.', how:'Markdown-файлы в KV, которые обновляет сам ассистент. По сути скилл Claude.', ex:'«Маша в отпуске 20–27» → задачи Маши на эти даты предлагает передать.'},\n  ctx:{side:'core', t:'Общий контекст', s:'Задачи, переписка и память в одном месте', what:'Задачи, история, база знаний и цифры собираются вместе, поэтому ИИ отвечает по делу, а не общими словами.', how:'Перед запросом воркер собирает выжимку из KV.', ex:'«Что я обещал клиентам и не сделал?» → список с датами и ссылками на переписку.'},\n  board:{side:'out', t:'Таск-трекер', s:'Веб-страница с задачами и фильтрами', what:'Все задачи команды: статусы, сроки, источник, история. Можно создать задачу текстом, как в чате.', how:'Страница на том же воркере, вход по паролю.', ex:'Фильтр «просрочено у Кости» → 2 задачи и история напоминаний.'},\n  nexec:{side:'out', t:'Уведомления исполнителям', s:'В личку от бота или в рабочий чат', what:'Каждый получает свои задачи и напоминания в личку от бота или упоминанием в рабочем чате, с кнопками «Готово», «Перенести», «Нужна помощь». Канал выбирается под команду и под задачу.', how:'Для лички сотрудник один раз пишет боту /start. Для чата бот уже сидит в группе.', ex:'«Маша, завтра в 18:00 срок по ретаргету. Всё по плану?»'},\n  nme:{side:'out', t:'Уведомления вам', s:'Брифинг и эскалации', what:'Утром сводка дня, днём только важное: эскалации, ответы клиентам, горящие сроки. Вечером итог.', how:'Отдельный режим для руководителя.', ex:'9:00: «Сегодня 4 срока, 1 просрочка у Кости, встреча в 15:00».'},\n  rep:{side:'out', t:'Отчёты', s:'Каждый день, по сотрудникам и проекту', what:'Ежедневный отчёт: что сделано и что сорвано, отдельно по каждому сотруднику и по проекту. Плюс итоги недели и отчёт собственнику в вашем формате, который ассистент запомнил.', how:'Claude по данным задач: каждый вечер по расписанию или по кнопке.', ex:'Каждый день в 19:00: «Маша 3 из 3 в срок, у Кости 1 просрочка. Реклама: 2 закрыто, 1 в работе».'},\n  askn:{side:'out', t:'Вопросы к ИИ', s:'В чате и на дашборде', what:'Спрашиваете что угодно: кто перегружен, что горит, что по клиенту. Ответ по живым данным.', how:'Окно на дашборде и команда /ask в боте.', ex:'«Кто сейчас перегружен?» → Костя: 6 открытых, 2 просрочены.'},\n  mdash:{side:'out', t:'Дашборд маркетинга', s:'Связка в обе стороны', what:'Дашборд создаёт задачи по аномалиям, а задачи видны рядом с цифрами: почему вырос CPL и кто уже разбирается.', how:'Общий воркер и общее хранилище.', ex:'Рядом с графиком CPL: «Маша проверяет кампании, срок сегодня».'}\n};\nvar srcOn = {tg:true,biz:true,mail:true,cal:true,crm:true,voice:true,dash:true};\nvar mapSel = 'tg';\nfunction alignPipes(){\n  [['#pipesL','#mapSources'],['#pipesR','#mapOutputs']].forEach(function(pr){\n    var box = $(pr[0]);\n    if (window.innerWidth < 900){ box.innerHTML = '<div class=\"pipe\"></div><div class=\"pipe\"></div><div class=\"pipe\"></div>'; return; }\n    var top = box.getBoundingClientRect().top;\n    box.innerHTML = $$(pr[1]+' .node').map(function(n){ var r = n.getBoundingClientRect(); return '<div class=\"pipe abs\" style=\"top:'+Math.round(r.top - top + r.height/2 - 1)+'px\"></div>'; }).join('');\n  });\n}\nwindow.addEventListener('resize', function(){ requestAnimationFrame(alignPipes); });\nfunction renderMap(){\n  var srcH = '<h4>Откуда приходят задачи</h4>', coreH = '<div class=\"ttl\"><i></i>🐱 ИИ-котёнок<span class=\"ttl-sub\">мурчит над задачами, ничего не теряет</span></div>', outH = '<h4>Что получаете</h4>';\n  Object.keys(NODES).forEach(function(k){\n    var n = NODES[k];\n    if (n.side==='src') {\n      srcH += '<button class=\"node'+(mapSel===k?' sel':'')+'\" data-node=\"'+k+'\"><span class=\"t\"><b>'+esc(n.t)+'</b><span>'+esc(n.s)+'</span></span></button>';\n    } else {\n      var h = '<button class=\"node'+(mapSel===k?' sel':'')+'\" data-node=\"'+k+'\"><span class=\"t\"><b>'+esc(n.t)+'</b><span>'+esc(n.s)+'</span></span></button>';\n      if (n.side==='core') coreH += h; else outH += h;\n    }\n  });\n  $('#mapSources').innerHTML = srcH; $('#mapCore').innerHTML = coreH; $('#mapOutputs').innerHTML = outH;\n  requestAnimationFrame(alignPipes);\n  var n = NODES[mapSel];\n  var tag = n.side==='src' ? 'Источник' : n.side==='core' ? 'OS' : 'Результат';\n  $('#mapDetail').innerHTML = '<div class=\"small muted\">'+tag+'</div><h3>'+esc(n.t)+'</h3>'+\n    '<div class=\"row\"><b>Что делает</b><div>'+esc(n.what)+'</div></div>'+\n    '<div class=\"row\"><b>Пример</b><div>'+esc(n.ex)+'</div></div>'+\n    '<div class=\"go\"><a class=\"btn sm\" href=\"#connect\" data-conn-go=\"'+mapSel+'\">Как подключить: '+esc(CONNECT[mapSel].time)+', '+CONNECT[mapSel].steps.length+' '+plural(CONNECT[mapSel].steps.length,'шаг','шага','шагов')+'</a></div>';\n}\ndocument.addEventListener('click', function(e){\n  var go = e.target.closest('[data-conn-go]');\n  if (go) { connSel = go.getAttribute('data-conn-go'); renderConnect(); return; }\n  var nd = e.target.closest('[data-node]');\n  if (nd) { mapSel = nd.getAttribute('data-node'); connSel = mapSel; renderMap(); renderConnect(); }\n});\n/* ───────── Как подключить ───────── */\nvar CONNECT = {\n  tg:{time:'30 минут', need:['Аккаунт Telegram','Cloudflare Worker','Сервис расшифровки для голосовых'], steps:[\n    'В @BotFather отправьте <code>/newbot</code>, задайте имя и username. Получите токен бота.',\n    'Там же <code>/setprivacy</code> → выберите бота → <b>Disable</b>. Без этого в группах бот видит только команды и упоминания.',\n    'Сохраните токен в секрет воркера: <code>wrangler secret put BOT_TOKEN</code>.',\n    'Поставьте вебхук на воркер: <code>https://api.telegram.org/bot&lt;ТОКЕН&gt;/setWebhook?url=https://&lt;воркер&gt;/webhook</code>.',\n    'Добавьте бота во все рабочие чаты. Можно сделать админом, тогда он точно видит всё.',\n    'Попросите каждого сотрудника один раз написать боту <code>/start</code>, иначе бот не сможет писать им в личку.',\n    '<b>Голосовые:</b> бот получает voice, скачивает файл через <code>getFile</code> и отправляет в расшифровку (Workers AI с Whisper или SpeechKit). Текст идёт в тот же разбор, что и обычные сообщения.',\n    'Предупредите команду в чате, что бот записывает задачи и сроки.'\n  ], tip:'Если privacy mode выключили, когда бот уже был в группе, удалите его и добавьте заново, иначе настройка не применится. Старую переписку до добавления бот не видит.'},\n  biz:{time:'20 минут', need:['Telegram Premium','Бот из BotFather','Тот же воркер'], steps:[\n    'В @BotFather: Bot Settings → <b>Business Mode</b> → включить.',\n    'В Telegram на своём аккаунте: Настройки → Telegram для бизнеса → Чат-боты → введите username бота.',\n    'Выберите, какие чаты видит бот: «все, кроме» исключённых или только выбранные. Личные переписки исключите.',\n    'Решите, давать ли боту право отвечать от вашего имени. Для задач и черновиков достаточно чтения.',\n    'Голосовые в личке бот расшифровывает так же, как в рабочих чатах: тот же сервис расшифровки.',\n    'В вебхуке добавьте типы обновлений <code>business_connection</code> и <code>business_message</code> в <code>allowed_updates</code>.',\n    'Проверьте: напишите себе с другого аккаунта «пришлите КП до пятницы» и ответьте «пришлю». У вас должна появиться задача.'\n  ], tip:'Без Premium пункта «Чат-боты» в настройках не будет. Бот видит только чаты, выбранные в настройке, и только с момента подключения.'},\n  mail:{time:'1–2 часа', need:['Google-аккаунт с почтой','Проект в Google Cloud'], steps:[\n    'В Google Cloud Console создайте проект и включите <b>Gmail API</b>.',\n    'Настройте экран согласия OAuth и создайте OAuth-клиент типа Web application, redirect URI на воркер.',\n    'Один раз войдите через Google. Воркер сохраняет refresh token в KV, client secret лежит в секрете воркера.',\n    'Cron раз в 10–15 минут забирает новые письма из «Входящих».',\n    'Рассылки, чеки и уведомления сервисов отсеиваются по категориям Gmail и отправителям, остальное идёт в разбор Claude.',\n    'Задачи из писем приходят вам в личку с кнопками «Принять» и «Уже сделал».'\n  ], tip:'Для Яндекс.Почты проще настроить правило пересылки нужных писем на адрес, который Cloudflare Email Routing передаёт воркеру. Для этого домен должен быть на Cloudflare.'},\n  cal:{time:'30 минут после почты', need:['Тот же проект в Google Cloud'], steps:[\n    'Включите <b>Google Calendar API</b> в том же проекте.',\n    'Добавьте в OAuth доступ <code>calendar.readonly</code>. Если ассистент будет сам ставить встречи, нужен доступ к событиям.',\n    'Войдите через Google ещё раз, чтобы выдать новый доступ.',\n    'Cron утром читает события на сегодня и завтра. За 15 минут до встречи бот присылает справку: кто это и что по нему открыто.',\n    'Сроки задач ассистент не ставит на время, когда вы на встречах.'\n  ], tip:'Если календарей несколько (рабочий, личный), выберите, какие читать. Личный лучше не подключать.'},\n  crm:{time:'1 час', need:['Доступ администратора в CRM'], steps:[\n    '<b>amoCRM:</b> Настройки → Интеграции → создать интеграцию, получить ключи или долгосрочный токен.',\n    'Там же настройте вебхуки на адрес воркера: новая сделка, смена этапа, новое примечание.',\n    '<b>Bitrix24:</b> Приложения → Разработчикам → Другое → входящий вебхук с правами на CRM и исходящий на нужные события.',\n    'Положите токен в секрет воркера.',\n    'Опишите правила: лид без ответа больше 2 часов, сделка без движения 7 дней, обещанный созвон. Cron проверяет их через API.',\n    'Задачи по сделкам уходят ответственному менеджеру, эскалации вам.'\n  ], tip:'Начните с одного-двух правил. Если сразу включить всё, менеджеры утонут в напоминаниях и перестанут их читать.'},\n  voice:{time:'1 час', need:['Zoom с облачной записью (платный тариф)','Права администратора Zoom'], steps:[\n    'В Zoom App Marketplace: Develop → Build App → приложение с <b>Server-to-Server OAuth</b>.',\n    'Выдайте доступ к облачным записям (cloud recording, чтение).',\n    'Подпишитесь на событие <code>recording.completed</code> с адресом воркера. Zoom сначала проверит адрес запросом <code>endpoint.url_validation</code>, воркер должен на него ответить.',\n    'В настройках Zoom включите облачную запись и аудио-транскрипт.',\n    'Когда запись готова, воркер забирает транскрипт, Claude делает итоги, решения и задачи по исполнителям.'\n  ], tip:'Предупреждайте участников, что созвон записывается и расшифровывается. Итоги показывайте человеку на подтверждение, прежде чем раздавать задачи.'},\n  dash:{time:'30 минут', need:['Дашборд с прошлого воркшопа'], steps:[\n    'Дашборд уже живёт на этом воркере, данные лежат в <code>/dashboard/data.json</code>.',\n    'Опишите правила: метрика, период, порог, ответственный. Например: CPL Директа вырос больше чем на 30% за 3 дня → Маше.',\n    'После каждого обновления дашборда cron сравнивает цифры с правилами.',\n    'Если порог пройден, создаётся задача ответственному и сообщение вам с причиной.'\n  ], tip:'Ставьте пороги по скользящему среднему за несколько дней, иначе будут ложные тревоги на выходных.'},\n  parse:{time:'полдня', need:['Ключ Claude API'], steps:[\n    'Создайте ключ в консоли Anthropic и положите в секрет воркера: <code>wrangler secret put CLAUDE_API</code>.',\n    'Опишите команду, проекты и правила: кто за что отвечает, какой срок по умолчанию.',\n    'Каждое сообщение уходит в Claude вместе с этим описанием. В ответ JSON: задача или нет, исполнитель, срок, приоритет, проект.',\n    'Если Claude не уверен, бот спрашивает кнопками: «Это задача? Кому? Какой срок?»',\n    'Неделю проверяйте карточки руками и правьте описание команды, пока разбор не станет точным.'\n  ], tip:'Не разбирайте каждое «ок» и «спасибо»: короткие ответы отсекайте ещё до запроса к модели, это экономит деньги.'},\n  dl:{time:'2 часа', need:['Cron-триггер воркера'], steps:[\n    'В <code>wrangler.toml</code> добавьте расписание: <code>crons = [\"*/15 * * * *\"]</code>.',\n    'Каждые 15 минут воркер смотрит сроки и решает, кому что отправить по лестнице напоминаний.',\n    'Настройте тон, тихие часы и эскалацию, как в разделе «Лестница напоминаний».',\n    'Отправленные напоминания записываются в историю задачи, чтобы не дублировать.'\n  ], tip:'Ставьте лимит: не больше трёх напоминаний по одной задаче. Дальше только эскалация руководителю.'},\n  kb:{time:'2 часа', need:['KV воркера'], steps:[\n    'Заведите три файла в KV: о вас, о проекте, о команде. Заполните стартовые факты сами.',\n    'При разборе сообщений Claude отмечает новые факты: отпуск, бюджет, договорённость, предпочтение.',\n    'Ассистент дописывает факт в нужный файл и пишет вам, что запомнил. Ошибку можно отменить кнопкой.',\n    'Выдержка из базы уходит в каждый запрос к Claude, поэтому ассистент учитывает её в ответах и решениях.'\n  ], tip:'Раз в месяц пролистайте файлы и удалите устаревшее. Старый бюджет или уволившийся сотрудник будут сбивать ассистента.'},\n  ctx:{time:'1 час', need:['Задачи и база знаний в KV'], steps:[\n    'Перед каждым вопросом воркер собирает выжимку: открытые задачи, недавние события, база знаний, цифры дашборда.',\n    'Выжимка и вопрос уходят в Claude, ответ возвращается в бот или на страницу.',\n    'Старые закрытые задачи сворачиваются в короткие итоги, чтобы контекст не разрастался.'\n  ], tip:'Если ответы стали общими, проверьте, что в выжимку попадает база знаний и последние задачи.'},\n  board:{time:'1 день', need:['Воркер','Пароль для входа'], steps:[\n    'Попросите Claude Code сделать страницу <code>/tasks</code> на том же воркере.',\n    'Задачи читаются из KV: колонки по статусам, фильтры по людям, проектам и источникам, история каждой задачи.',\n    'Поле «добавить задачу текстом» использует тот же разбор, что и бот.',\n    'Вход по паролю из секрета воркера, как у админки.'\n  ], tip:'Сделайте трекер главным местом правды: всё, что меняется в боте, сразу видно на странице, и наоборот.'},\n  nexec:{time:'2 часа', need:['Бот','Сотрудники нажали /start'], steps:[\n    'Для лички: после <code>/start</code> бот запоминает chat_id сотрудника и пишет ему напрямую.',\n    'Для рабочего чата: бот пишет в группу с упоминанием исполнителя.',\n    'Канал выбирается в настройках: по человеку, по проекту или по типу напоминания.',\n    'Кнопки «Готово», «Перенести», «Нужна помощь» приходят как inline-кнопки и сразу меняют задачу.'\n  ], tip:'Публичные пинги в общий чат используйте только для серьёзных просрочек, иначе они будут раздражать.'},\n  nme:{time:'1 час', need:['Ваш chat_id'], steps:[\n    'Ваш chat_id кладётся в секрет <code>ADMIN_ID</code>.',\n    'Для вас отдельный режим: утренний брифинг, эскалации, ответы клиентам. Мелкие напоминания команде вам не дублируются.',\n    'Брифинг в 9:00 и итог дня в 19:00 по расписанию cron.'\n  ], tip:'Если сообщений от бота стало слишком много, ужесточите фильтр: только эскалации и брифинг.'},\n  rep:{time:'2 часа', need:['Задачи в KV','Claude API'], steps:[\n    'Cron каждый день в 19:00 собирает, что закрыто, что сорвано и что в работе.',\n    'Отчёт делится по каждому сотруднику и по каждому проекту.',\n    'Claude пишет отчёт в вашем формате из базы знаний. Отправка в личку, в рабочий чат или на почту.',\n    'По понедельникам добавляются итоги недели и отчёт собственнику.'\n  ], tip:'Попросите ассистента начинать отчёт с проблем, а не с успехов: так его читают до конца.'},\n  askn:{time:'2 часа', need:['Claude API','Таск-трекер'], steps:[\n    'На странице трекера окно «Спросить ИИ», в боте команда <code>/ask</code>.',\n    'Вопрос уходит в Claude вместе с выжимкой контекста.',\n    'Ответ ссылается на конкретные задачи, чтобы можно было сразу открыть карточку.'\n  ], tip:'Сохраните частые вопросы как кнопки: «что горит», «кто перегружен», «что я обещал».'},\n  mdash:{time:'1 час', need:['Дашборд маркетинга на том же воркере'], steps:[\n    'Дашборд читает задачи из того же KV.',\n    'Рядом с метрикой показывается, кто уже разбирается и какой срок.',\n    'Задачу по метрике можно создать прямо с дашборда кнопкой.'\n  ], tip:'Закрывайте задачу по метрике только когда цифра вернулась в норму, а не когда «посмотрели».'}\n};\nvar connSel = 'tg';\nfunction renderConnect(){\n  var groups = [['Откуда приходят задачи','src'],['OS','core'],['Что получаете','out']];\n  $('#connList').innerHTML = groups.map(function(g){\n    return '<h4>'+g[0]+'</h4>'+Object.keys(NODES).filter(function(k){ return NODES[k].side===g[1]; }).map(function(k){\n      return '<button data-conn=\"'+k+'\" class=\"'+(k===connSel?'on':'')+'\">'+esc(NODES[k].t)+'<span>'+esc(CONNECT[k].time)+'</span></button>';\n    }).join('');\n  }).join('');\n  var n = NODES[connSel], c = CONNECT[connSel];\n  $('#connBody').innerHTML = '<h3>'+esc(n.t)+'</h3><p class=\"muted\" style=\"margin-top:4px\">'+esc(n.what)+'</p>'+\n    '<div class=\"meta\"><span class=\"tag g\">'+esc(c.time)+'</span>'+c.need.map(function(x){ return '<span class=\"tag\">'+esc(x)+'</span>'; }).join('')+'</div>'+\n    '<h4>Шаги</h4><ol>'+c.steps.map(function(x){ return '<li><span>'+x+'</span></li>'; }).join('')+'</ol>'+\n    '<div class=\"tip\"><b>Подводный камень.</b> '+esc(c.tip)+'</div>';\n}\n$('#connList').addEventListener('click', function(e){ var b = e.target.closest('[data-conn]'); if (!b) return; connSel = b.getAttribute('data-conn'); renderConnect(); });\nrenderMap(); renderConnect();\n\n/* ───────── 2. Разбор сообщения ───────── */\nvar L = '(?<![а-яёa-z0-9])', R = '(?![а-яёa-z0-9])';\nvar NAME_RE = [\n  {id:'masha', re:new RegExp(L+'(маш[аеиу]|машеньк[аеиу]|мари[яиюей])'+R,'i')},\n  {id:'dima', re:new RegExp(L+'(дим[аеуы]|димон|дмитри[йяюе])'+R,'i')},\n  {id:'anya', re:new RegExp(L+'(ан[яеию]|анн[аеуы])'+R,'i')},\n  {id:'kostya', re:new RegExp(L+'(кост[яеию]|константин[ау]?)'+R,'i')}\n];\nvar PROMISE_RE = new RegExp(L+'((я\\\\s+)?(сделаю|пришлю|скину|подготовлю|отправлю|позвоню|напишу|проверю|посмотрю|вернусь|созвонюсь|договорюсь|беру на себя|займусь))'+R,'i');\nvar REQUEST_RE = new RegExp(L+'(пришлите|подготовьте|отправьте|сделайте|скиньте|направьте|подпишите|согласуйте|нужно подписать|ждём от вас|ждем от вас)'+R,'i');\nvar ACT_RE = new RegExp(L+'(сдела[а-яё]*|подготов[а-яё]*|пришл[а-яё]*|скин[а-яё]*|отправ[а-яё]*|провер[а-яё]*|запуст[а-яё]*|обнов[а-яё]*|собер[а-яё]*|собрать|напиш[а-яё]*|написать|позвон[а-яё]*|созвон[а-яё]*|соглас[а-яё]*|займ[а-яё]*|посмотр[а-яё]*|исправ[а-яё]*|поправ[а-яё]*|оплат[а-яё]*|подпис[а-яё]*|подпиш[а-яё]*|обзвон[а-яё]*|выложи[а-яё]*|опублику[а-яё]*|свяж[а-яё]*|связаться|ответ[ьи][а-яё]*|сверста[а-яё]*|нарису[а-яё]*|придума[а-яё]*|настро[а-яё]*|перенес[а-яё]*|закаж[а-яё]*|отчита[а-яё]*|разбер[а-яё]*|разобраться|договор[ия][а-яё]*|готов[ия][а-яё]*|нужн[оа]|надо)'+R,'i');\nvar CHATTER_RE = /^\\s*(ок|окей|ok|спасибо|спс|понял[а]?|принято|супер|отлично|да|нет|ага|класс|good|👍|🔥|\\+)[\\s!.,)]*$/i;\nvar WD = [\n  {d:1, re:'понедельник[а-яё]*'},{d:2, re:'вторник[а-яё]*'},{d:3, re:'сред[аеуы]'},{d:4, re:'четверг[а-яё]*'},\n  {d:5, re:'пятниц[а-яё]*'},{d:6, re:'суббот[а-яё]*'},{d:0, re:'воскресень[а-яё]*'}\n];\nvar MONTHS = ['январ','феврал','март','апрел','ма[йя]','июн','июл','август','сентябр','октябр','ноябр','декабр'];\nvar PROJ = [\n  {p:'Реклама', re:new RegExp(L+'(реклам[а-яё]*|директ[а-яё]*|таргет[а-яё]*|ретаргет[а-яё]*|кампани[а-яё]*|cpl|ctr|vk ads|бюджет[а-яё]*)'+R,'i')},\n  {p:'Креативы', re:new RegExp(L+'(баннер[а-яё]*|обложк[а-яё]*|креатив[а-яё]*|макет[а-яё]*|дизайн[а-яё]*|лендинг[а-яё]*|сайт[а-яё]*|презентаци[а-яё]*)'+R,'i')},\n  {p:'Контент', re:new RegExp(L+'(пост[а-яё]*|сторис|контент[а-яё\\\\-]*|рилс[а-яё]*|блогер[а-яё]*|ролик[а-яё]*|видео)'+R,'i')},\n  {p:'Продажи', re:new RegExp(L+'(кп|клиент[а-яё]*|лид[а-яё]*|сделк[а-яё]*|обзвон[а-яё]*|кейс[а-яё]*|звонк[а-яё]*)'+R,'i')},\n  {p:'Финансы', re:new RegExp(L+'(акт[а-яё]*|сч[её]т[а-яё]*|договор[а-яё]*|оплат[а-яё]*)'+R,'i')},\n  {p:'Отчётность', re:new RegExp(L+'(отч[её]т[а-яё]*|отчита[а-яё]*|итог[а-яё]*)'+R,'i')}\n];\nfunction nextDow(fromDay, dow){ var cur = dowOf(fromDay); var add = (dow - cur + 7) % 7; if (add===0) add = 7; return fromDay + add; }\n\nfunction parseMsg(text, nowH, ctx){\n  ctx = ctx || {};\n  var t = text.trim(), spans = [], res = {text:t};\n  function mark(m, cls, offset){ if (m) spans.push({s:m.index + (offset||0), e:m.index + (offset||0) + m[0].length, c:cls}); }\n  if (!t) return {empty:true};\n  var today = dayIdx(nowH);\n  // исполнитель\n  var who = null, whoNote = '';\n  NAME_RE.forEach(function(n){ var m = t.match(n.re); if (m && !who){ who = n.id; mark(m,'m-who'); } });\n  var pm = t.match(PROMISE_RE), rq = t.match(REQUEST_RE);\n  if (!who && pm){ who = 'me'; whoNote = 'ваше обещание'; mark(pm,'m-who'); }\n  if (!who && rq){ who = 'me'; whoNote = 'просьба к вам'; mark(rq,'m-act'); }\n  // действие\n  var am = t.match(ACT_RE); if (am) mark(am,'m-act');\n  // приоритет\n  var pri = 'обычный';\n  var ph = t.match(new RegExp(L+'(срочно|сроч[а-яё]*|горит|asap|критично|важно|прямо сейчас)'+R,'i'));\n  var pl = t.match(new RegExp(L+'(не горит|не срочно|когда будет время|по возможности)'+R,'i'));\n  if (pl){ pri = 'низкий'; mark(pl,'m-pri'); } else if (ph){ pri = 'высокий'; mark(ph,'m-pri'); }\n  // срок\n  var day = null, hour = null, dueAbs = null, m;\n  if ((m = t.match(new RegExp(L+'(до|к|в|на)?\\\\s*конц[ау]\\\\s+недели'+R,'i')))) { day = nextDow(today-1, 5); if (day < today) day += 7; hour = 18; mark(m,'m-due'); }\n  else if ((m = t.match(new RegExp(L+'(до|к)?\\\\s*конц[ау]\\\\s+дня'+R,'i')))) { day = today; hour = 19; mark(m,'m-due'); }\n  else if ((m = t.match(new RegExp(L+'((до|к|на)\\\\s+)?послезавтра'+R,'i')))) { day = today+2; mark(m,'m-due'); }\n  else if ((m = t.match(new RegExp(L+'((до|к|на)\\\\s+)?завтра'+R,'i')))) { day = today+1; mark(m,'m-due'); }\n  else if ((m = t.match(new RegExp(L+'((до|к|на)\\\\s+)?сегодня'+R,'i')))) { day = today; mark(m,'m-due'); }\n  else if ((m = t.match(new RegExp(L+'через\\\\s+(\\\\d+|пару|два|три|неделю)\\\\s*(дн[а-яё]*|час[а-яё]*|недел[а-яё]*)?'+R,'i')))) {\n    var nmap = {'пару':2,'два':2,'три':3,'неделю':1}; var q = nmap[m[1].toLowerCase()] || parseInt(m[1],10);\n    var unit = (m[2]||'').toLowerCase();\n    if (m[1].toLowerCase()==='неделю' || unit.indexOf('недел')===0) day = today + 7*q;\n    else if (unit.indexOf('час')===0) dueAbs = nowH + q;\n    else day = today + q;\n    mark(m,'m-due');\n  }\n  else {\n    var wdm = null;\n    WD.forEach(function(w){ if (wdm) return; var r = t.match(new RegExp(L+'((до|к|в|во|на|в течение)\\\\s+)?'+w.re+R,'i')); if (r) wdm = {m:r, d:w.d}; });\n    if (wdm){ day = nextDow(today, wdm.d); if (dowOf(today)===wdm.d && /(^|\\s)(в|во)\\s/i.test(wdm.m[0])) day = today; mark(wdm.m,'m-due'); }\n    else if ((m = t.match(new RegExp(L+'(до|к)?\\\\s*(\\\\d{1,2})\\\\s+('+MONTHS.join('|')+')[а-яё]*'+R,'i')))) {\n      var mi = 0; MONTHS.forEach(function(mn,i){ if (new RegExp('^'+mn,'i').test(m[3])) mi = i; });\n      var dt = new Date(BASE); dt.setMonth(mi, parseInt(m[2],10)); dt.setHours(18,0,0,0); if (dt < at(nowH)) dt.setFullYear(dt.getFullYear()+1);\n      dueAbs = (dt - BASE)/3600e3; mark(m,'m-due');\n    }\n    else if ((m = t.match(/(\\d{1,2})[.\\/](\\d{1,2})(?![\\d:])/))) {\n      var dt2 = new Date(BASE); dt2.setMonth(parseInt(m[2],10)-1, parseInt(m[1],10)); dt2.setHours(18,0,0,0); if (dt2 < at(nowH)) dt2.setFullYear(dt2.getFullYear()+1);\n      dueAbs = (dt2 - BASE)/3600e3; mark(m,'m-due');\n    }\n    else if ((m = t.match(new RegExp(L+'(до|к)\\\\s+(\\\\d{1,2})\\\\s*-?\\\\s*(го|е|ое)?\\\\s*(числа)?'+R,'i'))) && (m[3]||m[4]||parseInt(m[2],10)>23)) {\n      var dn = parseInt(m[2],10); var dt3 = new Date(at(nowH)); dt3.setDate(dn); dt3.setHours(18,0,0,0); if (dt3 < at(nowH)) dt3.setMonth(dt3.getMonth()+1);\n      dueAbs = (dt3 - BASE)/3600e3; mark(m,'m-due');\n    }\n  }\n  // время\n  var tm = t.match(/(?:^|[^\\dа-яё])(в|к|до)\\s*(\\d{1,2})[:.](\\d{2})(?!\\d)/i);\n  var tm2 = t.match(new RegExp(L+'(в|к|до)\\\\s+(\\\\d{1,2})(\\\\s*(час[а-яё]*|ч|утра|вечера))?'+R+'(?!\\\\s*-?\\\\s*(го|е|ое|числа|'+MONTHS.join('|')+'))','i'));\n  var tmo = t.match(new RegExp(L+'(до обеда|к обеду|утром|вечером|после обеда)'+R,'i'));\n  if (tm){ hour = parseInt(tm[2],10) + parseInt(tm[3],10)/60; var off = tm[0].search(/[вкд]/i); spans.push({s:tm.index+off, e:tm.index+tm[0].length, c:'m-due'}); }\n  else if (tm2 && parseInt(tm2[2],10)<=23 && !(dueAbs!==null && !day)) { hour = parseInt(tm2[2],10); if (/вечера/i.test(tm2[0]) && hour<12) hour += 12; mark(tm2,'m-due'); }\n  else if (tmo){ var w = tmo[1].toLowerCase(); hour = w==='утром'?11 : (w==='вечером'?19 : (w==='после обеда'?16 : 13)); mark(tmo,'m-due'); }\n  if (dueAbs === null && (day!==null || hour!==null)) {\n    if (day===null){ day = today; if (D(day,hour) <= nowH) day = today+1; }\n    if (hour===null) hour = 18;\n    dueAbs = D(day,hour);\n  }\n  if (dueAbs === null && pri==='высокий') dueAbs = Math.ceil(nowH)+3;\n  // проект\n  var proj = null; PROJ.forEach(function(p){ if (proj) return; var r = t.match(p.re); if (r){ proj = p.p; mark(r,'m-proj'); } });\n  // задача или нет\n  var isTask = !CHATTER_RE.test(t) && (!!am || !!pm || !!rq || (dueAbs!==null && t.length>12));\n  var conf = isTask ? Math.min(97, 35 + (am||pm||rq?20:0) + (dueAbs!==null?20:0) + (who?15:0) + (proj?7:0)) : (CHATTER_RE.test(t) ? 96 : 70);\n  if (!who) { who = ctx.defaultWho || 'me'; whoNote = whoNote || 'не назван, ставлю вам'; }\n  // название\n  var title = t;\n  spans.filter(function(s){ return s.c==='m-due' || s.c==='m-pri'; }).sort(function(a,b){ return b.s-a.s; }).forEach(function(s){ title = title.slice(0,s.s) + ' ' + title.slice(s.e); });\n  NAME_RE.forEach(function(n){ title = title.replace(new RegExp('^\\\\s*'+n.re.source+'\\\\s*[,!:]?\\\\s*','i'),' '); title = title.replace(new RegExp('[,\\\\s]+'+n.re.source+'\\\\s*[,!:]?\\\\s*$','i'),' '); });\n  title = title.replace(new RegExp(L+'(пожалуйста|плиз|пжл|пж|будь добр[а]?|ок\\\\?|сможешь|можешь|сможете|можете|давай|надо|нужно|я|короче)'+R,'gi'),' ')\n               .replace(/[?!]+/g,' ').replace(/\\s*,\\s*,/g,',').replace(/\\s{2,}/g,' ').replace(/^[\\s,.:;—-]+|[\\s,.:;—-]+$/g,'').trim();\n  title = title.replace(new RegExp(L+'((до|к|на)\\\\s+)?(сегодня|завтра|послезавтра)'+R,'gi'),' ').replace(/\\s{2,}/g,' ')\n               .replace(/[\\s,]+(но|и|а|же)$/i,'').trim();\n  var VERB = [[/^(пришлите|пришлю|скиньте|скину|отправьте|отправлю|направьте)(\\s+(вам|мне|нам))?[\\s,]*/i,'Отправить '],[/^(подготовьте|подготовлю)[\\s,]*/i,'Подготовить '],[/^(сделайте|сделаю)[\\s,]*/i,'Сделать '],\n    [/^(подпишите)[\\s,]*/i,'Подписать '],[/^(согласуйте)[\\s,]*/i,'Согласовать '],[/^(позвоню)[\\s,]*/i,'Позвонить '],[/^(напишу)[\\s,]*/i,'Написать '],[/^(проверю)[\\s,]*/i,'Проверить '],[/^(посмотрю)[\\s,]*/i,'Посмотреть ']];\n  VERB.forEach(function(v){ title = title.replace(v[0], v[1]); });\n  title = title.trim();\n  if (title) title = title[0].toUpperCase() + title.slice(1);\n  if (title.length > 90) title = title.slice(0,88).replace(/\\s\\S*$/,'') + '…';\n  res.isTask = isTask; res.conf = conf; res.who = who; res.whoNote = whoNote; res.due = dueAbs; res.pri = pri; res.proj = proj || 'Общее'; res.title = title || t; res.spans = spans;\n  return res;\n}\nfunction highlight(text, spans){\n  var list = spans.slice().sort(function(a,b){ return a.s-b.s || (b.e-b.s)-(a.e-a.s); }), out = '', pos = 0;\n  list.forEach(function(s){ if (s.s < pos) return; out += esc(text.slice(pos, s.s)) + '<mark class=\"'+s.c+'\">' + esc(text.slice(s.s, s.e)) + '</mark>'; pos = s.e; });\n  return out + esc(text.slice(pos));\n}\nvar SAMPLES = [\n  'Маша, запусти до четверга ретаргет на тех, кто дошёл до корзины',\n  'Дима, сможешь к 15:00 поправить баннер на лендинге? Горит',\n  'Окей, спасибо!',\n  'Скину вам КП и кейсы завтра до обеда',\n  'Пришлите, пожалуйста, счёт и договор до 25-го',\n  'Аня, контент-план на следующую неделю, не горит, но до конца недели',\n  'Костя, через 2 дня отчитайся по обзвону тёплых лидов'\n];\n$('#parseSamples').innerHTML = SAMPLES.map(function(s,i){ return '<button class=\"chip\" data-sample=\"'+i+'\">'+esc(s.length>34 ? s.slice(0,32)+'…' : s)+'</button>'; }).join('');\n$('#parseSamples').addEventListener('click', function(e){ var b = e.target.closest('[data-sample]'); if (!b) return; $('#parseIn').value = SAMPLES[+b.getAttribute('data-sample')]; runParse(); });\nvar lastParse = null, parseT;\nfunction runParse(){\n  var r = parseMsg($('#parseIn').value, sim); lastParse = r;\n  if (r.empty){ $('#parseHl').innerHTML = '<span class=\"muted\">Напишите что-нибудь</span>'; $('#parseFields').innerHTML=''; $('#parseVerdict').innerHTML=''; $('#parseConf').innerHTML=''; $('#parseAdd').disabled = true; return; }\n  $('#parseHl').innerHTML = highlight(r.text, r.spans);\n  $('#parseVerdict').innerHTML = r.isTask ? '<span class=\"pill yes\">Это задача</span>' : '<span class=\"pill no\">Не задача, пропускаю</span>';\n  $('#parseConf').innerHTML = 'уверенность <span class=\"bar\"><i style=\"width:'+r.conf+'%\"></i></span><span class=\"mono\">'+r.conf+'%</span>';\n  $('#parseAdd').disabled = !r.isTask;\n  if (!r.isTask){ $('#parseFields').innerHTML = '<p class=\"muted\" style=\"font-size:13.5px\">Ассистент не будет создавать задачу и не будет никого дёргать. Обычные ответы, благодарности и болтовня просто остаются в чате.</p>'; return; }\n  var rows = [\n    ['Задача', esc(r.title)],\n    ['Исполнитель', whoDot(r.who) + (r.whoNote ? ' <span class=\"small muted\">· '+esc(r.whoNote)+'</span>' : '')],\n    ['Срок', r.due!==null ? esc(DAYS_FULL[at(r.due).getDay()]+', '+at(r.due).getDate()+'.'+pad(at(r.due).getMonth()+1)+' в '+clock(r.due)) : '<span class=\"muted\">не указан, спрошу у исполнителя</span>'],\n    ['Приоритет', esc(r.pri)],\n    ['Проект', esc(r.proj)],\n    ['Напомню', r.due!==null ? esc(remindPlan(r)) : 'после уточнения срока']\n  ];\n  $('#parseFields').innerHTML = rows.map(function(x,i){ return '<div class=\"field\" style=\"animation-delay:'+(i*70)+'ms\"><b>'+x[0]+'</b><span>'+x[1]+'</span></div>'; }).join('');\n}\nfunction remindPlan(r){\n  var p = [], left = r.due - sim;\n  if (left > 26) p.push('за сутки');\n  if (left > 3) p.push('за 2 часа');\n  p.push('через час после срока');\n  if (r.who !== 'me' && settings.escalate) p.push('вам, если молчит 4 часа');\n  return p.join(', ');\n}\n$('#parseIn').addEventListener('input', function(){ clearTimeout(parseT); parseT = setTimeout(runParse, 180); });\n$('#parseAdd').addEventListener('click', function(){\n  if (!lastParse || !lastParse.isTask) return;\n  addTask(lastParse.title, lastParse.who, lastParse.due!==null ? lastParse.due : sim+24, 'web', lastParse.proj);\n  toast('Задача на доске · <a href=\"#board\">открыть</a>');\n});\n\n/* ───────── 4. Доска (общее состояние) ───────── */\nvar sim = 0, tasks = [], tid = 0, freshIds = {};\nfunction T(title, who, due, src, proj, o){ o = o||{}; return {id:++tid, title:title, who:who, due:due, src:src, proj:proj, status0:o.status||'todo', created:o.created!=null?o.created:-6, startAt:o.startAt!=null?o.startAt:null, doneAt:o.doneAt!=null?o.doneAt:null}; }\nfunction seed(){\n  tid = 0;\n  tasks = [\n    T('Креативы для ретаргета: 3 формата','dima', D(0,17),'tg','Креативы',{status:'doing',created:-20,doneAt:D(0,19)}),\n    T('Запустить ретаргет на брошенные корзины','masha', D(1,18),'tg','Реклама',{status:'doing',created:-20,doneAt:D(1,16)}),\n    T('КП и кейсы для ООО «Ромашка»','me', D(3,12),'biz','Продажи',{created:-2}),\n    T('Контент-план на следующую неделю','anya', D(2,18),'tg','Контент',{created:-26,startAt:D(1,11),doneAt:D(2,15)}),\n    T('Обзвонить тёплых лидов с вебинара (23 контакта)','kostya', D(1,15),'voice','Продажи',{status:'doing',created:-4}),\n    T('Подписать акты за сентябрь','me', D(5,18),'mail','Финансы',{created:-1}),\n    T('Отчёт собственнику за неделю','me', D(4,11),'web','Отчётность',{created:-30}),\n    T('Разобраться, почему упал CTR в VK Ads','masha', D(0,9),'dash','Реклама',{created:-24,doneAt:D(0,13)}),\n    T('Баннер на лендинг под акцию','dima', D(4,15),'tg','Креативы',{created:-3,startAt:D(3,10),doneAt:D(4,13)}),\n    T('Ответить блогеру по интеграции','me', D(0,14),'biz','Контент',{created:-18}),\n    T('Сторис с отзывами клиентов','anya', D(-1,16),'tg','Контент',{status:'done',created:-50,doneAt:-20}),\n    T('Связаться с «Альфа-Строй»: сделка 7 дней без движения','kostya', D(0,16),'crm','Продажи',{created:-1,doneAt:D(0,15)}),\n    T('Согласовать сценарий ролика со студией «Кадр»','anya', D(2,12),'cal','Контент',{created:-6,startAt:D(1,15),doneAt:D(2,17)}),\n    T('Отправить партнёрам условия реферальной программы','kostya', D(3,18),'tg','Продажи',{created:-2})\n  ];\n}\nseed();\nfunction addTask(title, who, due, src, proj){\n  var t = T(title, who, Math.max(due, sim+1), src, proj, {created:sim});\n  tasks.push(t); freshIds[t.id] = true; renderBoard();\n  return t;\n}\nfunction statusAt(t, h){\n  if (t.created > h) return null;\n  if (t.doneAt!==null && t.doneAt<=h) return 'done';\n  if (t.startAt!==null && t.startAt<=h) return 'doing';\n  return t.status0==='done' ? 'todo' : t.status0;\n}\nfunction isOpen(t,h){ var s = statusAt(t,h); return s && s!=='done'; }\n\n/* настройки напоминаний (раздел 5) */\nvar settings = {tone:'normal', quiet:true, escalate:true, chat:false};\nvar TONES = {soft:'Мягко', normal:'По делу', hard:'Жёстко'};\nvar ALT_OF = {masha:'Аню', dima:'Аню', anya:'Машу', kostya:'Аню', me:'Машу'};\nfunction msgText(kind, t, extra){\n  var n = TEAM[t.who].name, ti = '«'+t.title+'»', tone = settings.tone, tm = fmt(t.due);\n  var M = {\n    'new':  {soft:n+', привет! Новая задача '+ti+', срок '+tm+'. Если срок неудобный, скажи.', normal:n+', новая задача: '+ti+'. Срок '+tm+'. Принять?', hard:n+', задача '+ti+'. Срок '+tm+'. Подтверди до конца дня.'},\n    'd24':  {soft:n+', завтра срок по '+ti+'. Если нужна помощь, напиши.', normal:n+', завтра в '+clock(t.due)+' срок: '+ti+'. Всё по плану?', hard:n+', срок завтра в '+clock(t.due)+': '+ti+'. Статус нужен до 18:00.'},\n    'd2':   {soft:'Через пару часов срок по '+ti+'. Успеваешь?', normal:n+', через 2 часа срок: '+ti+'.', hard:n+', 2 часа до срока по '+ti+'. Если не успеваешь, пиши сейчас.'},\n    'over': {soft:n+', кажется, срок по '+ti+' прошёл. Подскажи, когда получится?', normal:n+', '+ti+' просрочена на час. Какой новый срок?', hard:n+', '+ti+' просрочена. Через 3 часа сообщу руководителю.'},\n    'overMe': {soft:'Срок по вашей задаче '+ti+' прошёл. Перенести?', normal:'Вы просрочили '+ti+'. Перенести или сделать сейчас?', hard:'Просрочено у вас: '+ti+'. Подаёте пример команде.'},\n    'esc':  {soft:'Похоже, '+n+' застрял(а) на '+ti+'. Может, нужна помощь?', normal:'Эскалация: '+ti+' ('+n+') просрочена на 4 часа, ответа нет.', hard:'Эскалация: '+n+' молчит 4 часа по '+ti+'. Предлагаю передать задачу: '+ALT_OF[t.who]+'.'},\n    'chat': {soft:'', normal:'', hard:'В чат «Маркетинг»: '+ti+' просрочена на сутки. '+n+', отпишись по статусу.'},\n    'done': {soft:n+' закрыл(а) '+ti+(extra||''), normal:n+' закрыл(а) '+ti+(extra||''), hard:n+' закрыл(а) '+ti+(extra||'')}\n  };\n  return M[kind][tone];\n}\nfunction quietShift(t){\n  if (!settings.quiet) return t;\n  var c = ((10+t)%24+24)%24;\n  if (c >= 21) return t + (24-c) + 9;\n  if (c < 9) return t + (9-c);\n  return t;\n}\nfunction eventsFor(t){\n  var ev = [], end = t.doneAt!==null ? t.doneAt : Infinity, me = t.who==='me';\n  function add(time, kind, to, ch, noShift){ var tt = noShift ? time : quietShift(time); if (kind!=='done' && tt >= end) return; if (tt < 0 || tt < t.created) return; ev.push({t:tt, kind:kind, to:to, ch:ch, task:t}); }\n  if (t.created >= 0) add(t.created, 'new', t.who, me?'вам':'в личку');\n  if (t.due-24 > t.created) add(t.due-24, 'd24', t.who, me?'вам':'в личку');\n  if (t.due-2 > t.created) add(t.due-2, 'd2', t.who, me?'вам':'в личку');\n  add(t.due+1, me?'overMe':'over', t.who, me?'вам':'в личку');\n  if (!me && settings.escalate) add(t.due+4, 'esc', 'me', 'вам');\n  if (!me && settings.tone==='hard' && settings.chat) add(t.due+24, 'chat', 'group', 'в общий чат');\n  if (t.doneAt!==null && t.doneAt>=0 && !me) add(t.doneAt, 'done', 'me', 'вам', true);\n  return ev;\n}\nfunction briefAt(h){\n  var open = tasks.filter(function(t){ return isOpen(t,h); });\n  var today = open.filter(function(t){ return dayIdx(t.due)===dayIdx(h) && t.due>=h; }).length;\n  var over = open.filter(function(t){ return t.due < h; });\n  var mine = open.filter(function(t){ return t.who==='me'; }).length;\n  var s = 'Доброе утро. Сегодня сроков: '+today+'. ';\n  s += over.length ? 'Просрочено: '+over.length+' ('+over.map(function(t){ return TEAM[t.who].name; }).filter(function(v,i,a){ return a.indexOf(v)===i; }).join(', ')+'). ' : 'Просрочек нет. ';\n  s += 'Ваших открытых задач: '+mine+'.';\n  return s;\n}\nfunction allEvents(){\n  var ev = [];\n  tasks.forEach(function(t){ ev = ev.concat(eventsFor(t)); });\n  for (var k=1;k<=7;k++){ var h = D(k,9); ev.push({t:h, kind:'brief', to:'me', ch:'вам', brief:true}); }\n  return ev.sort(function(a,b){ return a.t-b.t; });\n}\nfunction evText(e){\n  if (e.brief) return briefAt(e.t);\n  if (e.kind==='done'){ var late = e.task.doneAt - e.task.due; return msgText('done', e.task, late>0 ? ' с опозданием на '+hrs(late)+'.' : ' вовремя.'); }\n  return msgText(e.kind, e.task);\n}\nvar EV_LABEL = {'new':'новая задача', d24:'за сутки', d2:'за 2 часа', over:'просрочка', overMe:'просрочка', esc:'эскалация', chat:'пинг в чат', done:'закрыто', brief:'брифинг 9:00'};\n\nvar whoF = 'all', onlyOver = false, seenEv = 0;\nfunction renderBoard(){\n  var h = sim;\n  $('#tmNow').textContent = fmt(h);\n  $('#tmLabel').textContent = h===0 ? 'начало демо, '+DAYS_FULL[at(0).getDay()] : 'прошло '+hrs(h);\n  $('#tmRange').value = h;\n  var vis = tasks.filter(function(t){ return statusAt(t,h); });\n  var open = vis.filter(function(t){ return isOpen(t,h); });\n  var over = open.filter(function(t){ return t.due < h; });\n  var today = open.filter(function(t){ return dayIdx(t.due)===dayIdx(h) && t.due>=h; });\n  var done = vis.filter(function(t){ return statusAt(t,h)==='done' && t.doneAt>=0; });\n  var onTime = done.filter(function(t){ return t.doneAt <= t.due; }).length;\n  $('#kOpen').textContent = open.length; $('#kOver').textContent = over.length; $('#kToday').textContent = today.length;\n  $('#kOnTime').textContent = done.length ? Math.round(onTime/done.length*100)+'%' : '—';\n  var cols = {todo:[], doing:[], done:[]};\n  vis.forEach(function(t){\n    if (whoF!=='all' && t.who!==whoF) return;\n    var s = statusAt(t,h);\n    if (onlyOver && !(s!=='done' && t.due<h)) return;\n    cols[s].push(t);\n  });\n  var names = {todo:'Новые', doing:'В работе', done:'Готово'};\n  $('#kanban').innerHTML = ['todo','doing','done'].map(function(c){\n    var list = cols[c].sort(function(a,b){ return c==='done' ? b.doneAt-a.doneAt : a.due-b.due; });\n    return '<div class=\"kcol\"><h4>'+names[c]+'<span>'+list.length+'</span></h4><div class=\"kcards\">'+\n      (list.length ? list.map(function(t){\n        var st = statusAt(t,h), r = st==='done' ? {t: fmt(t.doneAt), c: t.doneAt<=t.due ? 'ok' : 'over'} : relDue(t.due,h);\n        var overC = st!=='done' && t.due<h;\n        return '<button class=\"tk'+(overC?' over':'')+(freshIds[t.id]?' fresh':'')+'\" data-task=\"'+t.id+'\" title=\"Нажмите, чтобы сменить статус\"><div class=\"tt\">'+esc(t.title)+'</div><div class=\"mt\"><span class=\"who-dot\">'+esc(TEAM[t.who].name)+'</span><span class=\"due '+r.c+'\">'+esc(r.t)+'</span></div></button>';\n      }).join('') : '<div class=\"empty\">Пусто</div>')+'</div></div>';\n  }).join('');\n  // лента\n  var ev = allEvents().filter(function(e){ return e.t <= h; });\n  $('#feedCount').textContent = ev.length + ' ' + plural(ev.length,'сообщение','сообщения','сообщений');\n  var shown = ev.slice(-40).reverse(), newN = Math.max(0, ev.length - seenEv);\n  $('#feed').innerHTML = shown.length ? shown.map(function(e,i){\n    var to = e.to==='group' ? 'Чат «Маркетинг»' : e.to==='me' ? 'Вам' : TEAM[e.to].name;\n    return '<div class=\"ev k-'+e.kind+(i<newN && seenEv>0 ? ' new' : '')+'\"><div class=\"eh\"><span><b>'+esc(to)+'</b> · '+esc(EV_LABEL[e.kind])+'</span><span class=\"mono\">'+fmt(e.t)+'</span></div>'+esc(evText(e))+'</div>';\n  }).join('') : '<div class=\"empty\">Пока тихо. Подвиньте время вперёд, и ассистент начнёт напоминать.</div>';\n  seenEv = ev.length;\n  $('#askCtx').textContent = 'видит '+vis.length+' '+plural(vis.length,'задачу','задачи','задач')+', 5 человек, сейчас '+fmt(h);\n  setTimeout(function(){ freshIds = {}; }, 50);\n}\n$('#whoFilter').innerHTML = '<button class=\"chip on\" data-who=\"all\">Все</button>' + TEAM_IDS.map(function(id){ return '<button class=\"chip\" data-who=\"'+id+'\">'+esc(TEAM[id].name)+'</button>'; }).join('');\n$('#whoFilter').addEventListener('click', function(e){ var b = e.target.closest('[data-who]'); if (!b) return; whoF = b.getAttribute('data-who'); $$('#whoFilter .chip').forEach(function(c){ c.classList.toggle('on', c===b); }); renderBoard(); });\n$('#onlyOver').addEventListener('click', function(){ onlyOver = !onlyOver; this.classList.toggle('on', onlyOver); renderBoard(); });\n$('#kanban').addEventListener('click', function(e){\n  var b = e.target.closest('[data-task]'); if (!b) return;\n  var t = tasks.filter(function(x){ return x.id === +b.getAttribute('data-task'); })[0]; var s = statusAt(t, sim);\n  if (s==='todo'){ t.startAt = sim; if (t.doneAt!==null && t.doneAt<=sim) t.doneAt = null; }\n  else if (s==='doing'){ t.doneAt = sim; }\n  else { t.doneAt = null; t.startAt = null; t.status0 = 'todo'; }\n  if (s==='todo' && t.doneAt!==null && t.doneAt<sim) t.doneAt = null;\n  renderBoard();\n});\nfunction setSim(h){ sim = Math.max(0, Math.min(168, Math.round(h))); renderBoard(); if (lastParse) runParse(); }\n$('#tmRange').addEventListener('input', function(){ setSim(+this.value); });\n$('#tmDay').addEventListener('click', function(){ setSim(sim+24); });\nvar playT = null;\nfunction stopPlay(){ clearInterval(playT); playT = null; $('#tmPlay').textContent = 'Пустить время'; }\n$('#tmPlay').addEventListener('click', function(){\n  if (playT){ stopPlay(); return; }\n  if (sim >= 168) setSim(0);\n  this.textContent = 'Пауза';\n  playT = setInterval(function(){ if (sim >= 168){ stopPlay(); return; } setSim(sim+1); }, 140);\n});\n$('#tmReset').addEventListener('click', function(){ stopPlay(); seed(); seenEv = 0; firedRules = {}; renderRules(); setSim(0); toast('Демо сброшено'); });\n$('#qadd').addEventListener('submit', function(e){\n  e.preventDefault(); var v = $('#qaddIn').value.trim(); if (!v) return;\n  var r = parseMsg(v, sim);\n  if (!r.isTask){ toast('Похоже, это не задача. Добавьте действие и срок: «Аня, пост к пятнице»'); return; }\n  addTask(r.title, r.who, r.due!==null ? r.due : sim+24, 'web', r.proj);\n  $('#qaddIn').value = '';\n  toast('Добавлено: '+esc(TEAM[r.who].name)+', '+esc(r.due!==null ? fmt(r.due) : 'срок через сутки'));\n});\nvar CHAOS = [\n  ['Маша, до завтра собери отчёт по расходам в Директе','tg'],\n  ['Дима, срочно обложка для вебинара к 16:00','tg'],\n  ['Пришлите, пожалуйста, медиаплан до четверга','biz'],\n  ['Аня, через 2 дня пост с итогами вебинара','voice'],\n  ['Костя, сегодня до конца дня позвони трём горячим лидам','crm']\n];\n$('#chaos').addEventListener('click', async function(){\n  this.disabled = true;\n  for (var i=0;i<CHAOS.length;i++){ var r = parseMsg(CHAOS[i][0], sim); addTask(r.title, r.who, r.due!==null ? r.due : sim+24, CHAOS[i][1], r.proj); await sleep(reduce?0:350); }\n  toast('Понедельник наступил: +5 задач из чатов, лички и CRM');\n  this.disabled = false;\n});\n\n/* ───────── 5. Лестница напоминаний ───────── */\n$('#toneTabs').innerHTML = Object.keys(TONES).map(function(k){ return '<button data-tone=\"'+k+'\" class=\"'+(settings.tone===k?'on':'')+'\">'+TONES[k]+'</button>'; }).join('');\n$('#toneTabs').addEventListener('click', function(e){ var b = e.target.closest('[data-tone]'); if (!b) return; settings.tone = b.getAttribute('data-tone'); $$('#toneTabs button').forEach(function(x){ x.classList.toggle('on', x===b); }); renderLadder(); renderBoard(); });\n$('#optQuiet').addEventListener('change', function(){ settings.quiet = this.checked; renderLadder(); renderBoard(); });\n$('#optEsc').addEventListener('change', function(){ settings.escalate = this.checked; renderLadder(); renderBoard(); if (lastParse) runParse(); });\n$('#optChat').addEventListener('change', function(){ settings.chat = this.checked; if (this.checked && settings.tone!=='hard'){ settings.tone='hard'; $$('#toneTabs button').forEach(function(x){ x.classList.toggle('on', x.getAttribute('data-tone')==='hard'); }); toast('Публичный пинг работает только в режиме «Жёстко», включил его'); } renderLadder(); renderBoard(); });\nfunction renderLadder(){\n  var ex = {title:'Запустить ретаргет на брошенные корзины', who:'masha', due:D(nextDow(0,4),18)};\n  var steps = [\n    {t:0, to:'Маше в личку', k:'new'},\n    {t:ex.due-24, to:'Маше в личку', k:'d24'},\n    {t:ex.due-2, to:'Маше в личку', k:'d2'},\n    {t:quietShift(ex.due+1), to:'Маше в личку', k:'over'},\n    {t:quietShift(ex.due+4), to:'Вам', k:'esc', cls:'esc', off:!settings.escalate},\n    {t:quietShift(ex.due+24), to:'В общий чат', k:'chat', cls:'chat', off:!(settings.chat && settings.tone==='hard')}\n  ];\n  steps.forEach(function(s){ s.when = fmt(s.t); });\n  $('#ladder').innerHTML = steps.map(function(s){\n    var txt = s.k==='chat' ? (msgText('chat', ex) || 'Только в режиме «Жёстко»') : msgText(s.k, ex);\n    var qn = '';\n    if (settings.quiet && s.k==='esc') qn = '<div class=\"to\" style=\"margin-top:6px\">Без тихих часов ушло бы '+fmt(ex.due+4)+'</div>';\n    return '<div class=\"step '+(s.cls||'')+(s.off?' off':'')+'\"><div class=\"when\">'+s.when+'</div><div class=\"to\">'+s.to+'</div><div class=\"bubble\">'+esc(txt)+'</div>'+qn+'</div>';\n  }).join('');\n}\nrenderLadder();\n\n/* ───────── 3. Сцены в чатах ───────── */\nfunction W(dow, hour){ return fmt(D(nextDow(0,dow),hour)); }\nvar DAY25 = (function(){ var d = new Date(BASE); d.setDate(25); d.setHours(18,0,0,0); if (d < BASE) d.setMonth(d.getMonth()+1); return (d-BASE)/3600e3; })();\nvar SCENES = {\n  team:{tab:'Рабочий чат', title:'Маркетинг', sub:'5 участников, ассистент', ava:'М', color:'#0E7C86',\n    side:'<h3>Бот в рабочем чате</h3><p>Ассистент сидит в группе как обычный участник. Пишет только когда видит задачу, срок или проблему, остальное время молчит.</p><ul><li>Сам находит исполнителя и срок в обычной фразе.</li><li>Замечает зависимости: креативы нужны раньше запуска.</li><li>Переносит срок по одной фразе и проверяет, что запуск не сдвигается.</li></ul>',\n    s:[\n      {who:'me', text:'Маша, запусти до четверга ретаргет на тех, кто дошёл до корзины'},\n      {who:'bot', text:'Записал задачу', card:{t:'Запустить ретаргет на брошенные корзины', m:['Маша',W(4,18),'Реклама']}, btns:['Принять','Другой срок']},\n      {who:'masha', text:'ок, но мне нужны креативы от Димы'},\n      {who:'bot', text:'Создал связанную задачу. Креативы нужны за день до запуска, поэтому срок среда.', card:{t:'Креативы для ретаргета, 3 формата', m:['Дима',W(3,15),'Креативы']}, btns:['Принять','Другой срок']},\n      {div:W(3,10)},\n      {who:'bot', text:'Дима, сегодня в 15:00 срок по креативам для ретаргета. Успеваешь?'},\n      {who:'dima', text:'скину к 17, доделываю видео'},\n      {who:'bot', text:'Перенёс срок на '+W(3,17)+'. Маша, запуск в четверг не сдвигается, креативы будут вечером.'},\n      {div:W(4,16+40/60)},\n      {who:'masha', text:'Запустила, бюджет 5к в день'},\n      {who:'bot', text:'Закрыл задачу «Запустить ретаргет». Записал в базу знаний: бюджет ретаргета 5 000 ₽ в день.'}\n    ]},\n  biz:{tab:'Личка с клиентом', title:'Иван Петров', sub:'ООО «Ромашка» · Business-бот видит чат', ava:'И', color:'#5B4BD6',\n    side:'<h3>Business-бот в вашей личке</h3><p>Клиент пишет вам, а не боту. Ассистент тихо читает переписку и ловит просьбы и ваши обещания. Сообщения на сиреневом фоне видите только вы.</p><ul><li>Ваше «да, пришлю» становится задачей с честным сроком.</li><li>Карточка клиента в CRM обновляется сама.</li><li>Накануне срока готов черновик, вам остаётся проверить.</li></ul>',\n    s:[\n      {who:'client', text:'Добрый день! Пришлите, пожалуйста, КП и пару кейсов до пятницы. Покажу директору.'},\n      {who:'me', text:'Добрый! Да, конечно, пришлю'},\n      {sys:'Ассистент поймал обещание → задача вам: «КП и кейсы для ООО «Ромашка»», срок '+W(5,12)+'. Карточка клиента в CRM обновлена.'},\n      {who:'client', text:'И ещё: созвониться нам удобно только после 15:00'},\n      {sys:'Записал в базу знаний: «Ромашка», созвоны только после 15:00. Не предложу слоты раньше.'},\n      {div:W(4,19)},\n      {sys:'Завтра до 12:00 обещали Ивану КП. Черновик по шаблону и 2 кейса из похожей ниши готовы.', btns:['Открыть черновик','Перенести на понедельник']},\n      {div:W(5,11+20/60)},\n      {who:'me', text:'Иван, отправляю КП и кейсы. Удобно обсудить сегодня в 16:00?'},\n      {sys:'Задача закрыта вовремя. Предложил время после 15:00, как просил клиент.'}\n    ]},\n  mail:{tab:'Почта и календарь', title:'Ассистент', sub:'бот · личные сообщения', ava:'🐱', color:'cat',\n    side:'<h3>Почта и календарь</h3><p>Ассистент читает входящие и календарь и пишет вам в личку только то, что требует действия. Рассылки и уведомления сервисов отсеивает.</p><ul><li>Письмо с дедлайном становится задачей.</li><li>Перед встречей приходит справка по контрагенту.</li><li>Конфликты сроков со встречами видны заранее.</li></ul>',\n    s:[\n      {who:'bot', text:'Новое письмо от бухгалтерии: «Нужно подписать акты за сентябрь до 25-го».', card:{t:'Подписать акты за сентябрь', m:['Вы',fmt(DAY25),'Финансы']}, btns:['Принять','Уже сделал']},\n      {who:'bot', text:'Ещё 14 писем разобрал: рассылки, уведомления сервисов, чеки. Задач в них нет.'},\n      {div:fmt(D(0,14.75))},\n      {who:'bot', text:'Через 15 минут встреча со студией «Кадр». По ним открыто: «Согласовать сценарий ролика» (Аня, срок '+W(3,12)+'). В прошлый раз договорились о двух вариантах финала.'},\n      {who:'me', text:'Спасибо. Что ещё у меня сегодня горит?'},\n      {who:'bot', text:'До вечера: ответить блогеру по интеграции (просрочено на 1 ч) и проверить отчёт Маши по CTR. Остальное терпит до завтра.'}\n    ]},\n  voice:{tab:'Голосовое', title:'Маркетинг', sub:'5 участников, ассистент', ava:'М', color:'#0E7C86',\n    side:'<h3>Голосовое на бегу</h3><p>Наговорили из машины 40 секунд, а ассистент расшифровал, понял, кому что, и раскидал задачи. Так же работает с записью созвона: протокол и задачи по итогам.</p><ul><li>Несколько исполнителей в одном сообщении.</li><li>Свои обещания внутри голосового тоже ловятся.</li><li>Каждый получает только свою часть.</li></ul>',\n    s:[\n      {who:'me', voice:'0:41'},\n      {who:'bot', text:'Расшифровка: «Короче, по запуску. Аня готовит посты на неделю к понедельнику, Костя до среды обзванивает тёплых лидов с вебинара, а я договорюсь с блогером про интеграцию».'},\n      {who:'bot', text:'Создал 3 задачи:', card:{t:'Посты на неделю запуска', m:['Аня',W(1,18),'Контент']}},\n      {who:'bot', card:{t:'Обзвонить тёплых лидов с вебинара', m:['Костя',W(3,18),'Продажи']}},\n      {who:'bot', card:{t:'Договориться с блогером об интеграции', m:['Вы',W(5,18),'Контент']}, btns:['Всё верно','Поправить']},\n      {who:'anya', text:'Принято'},\n      {who:'kostya', text:'там 23 контакта, до среды норм'}\n    ]},\n  brief:{tab:'Утренний брифинг', title:'Ассистент', sub:'бот · личные сообщения', ava:'🐱', color:'cat',\n    side:'<h3>Утро руководителя</h3><p>В 9:00 приходит сводка дня, собранная по живой доске из раздела 4. Сдвиньте там время или закройте задачи и запустите сцену снова: брифинг изменится.</p><ul><li>Сроки на сегодня и просрочки.</li><li>Что ждут от вас лично.</li><li>Один совет, на что потратить утро.</li></ul>',\n    s:null}\n};\nvar scnCur = 'team', scnTok = 0;\n$('#scnTabs').innerHTML = Object.keys(SCENES).map(function(k){ return '<button role=\"tab\" data-scn=\"'+k+'\" class=\"'+(k===scnCur?'on':'')+'\">'+SCENES[k].tab+'</button>'; }).join('');\n$('#scnTabs').addEventListener('click', function(e){ var b = e.target.closest('[data-scn]'); if (!b) return; scnCur = b.getAttribute('data-scn'); $$('#scnTabs button').forEach(function(x){ x.classList.toggle('on', x===b); }); loadScene(true); });\nvar PEOPLE = {me:{n:'Вы', c:'#2B4ACB'}, masha:{n:'Маша', c:'#0E7C86'}, dima:{n:'Дима', c:'#B7791F'}, anya:{n:'Аня', c:'#5B4BD6'}, kostya:{n:'Костя', c:'#C4373C'}, client:{n:'Иван Петров', c:'#5B4BD6'}, bot:{n:'Ассистент', c:'#2B4ACB'}};\nfunction briefScript(){\n  var h = Math.max(sim, 0), open = tasks.filter(function(t){ return isOpen(t,h); });\n  var today = open.filter(function(t){ return dayIdx(t.due)===dayIdx(h) && t.due>=h; });\n  var over = open.filter(function(t){ return t.due<h; });\n  var mine = open.filter(function(t){ return t.who==='me'; }).sort(function(a,b){ return a.due-b.due; });\n  var s = [{div:DAYS_FULL[at(h).getDay()]+', 9:00'}];\n  s.push({who:'bot', text:'Доброе утро. Сегодня '+today.length+' '+plural(today.length,'срок','срока','сроков')+', просрочено '+over.length+'.'});\n  if (over.length) s.push({who:'bot', text:'Просрочено: '+over.slice(0,4).map(function(t){ return TEAM[t.who].name+' — «'+t.title+'»'; }).join('; ')+'.'});\n  if (mine.length) s.push({who:'bot', text:'Ждут от вас: '+mine.slice(0,3).map(function(t){ return '«'+t.title+'» ('+relDue(t.due,h).t+')'; }).join(', ')+'.'});\n  var load = {}; open.forEach(function(t){ load[t.who] = (load[t.who]||0)+1; });\n  var top = Object.keys(load).filter(function(k){ return k!=='me'; }).sort(function(a,b){ return load[b]-load[a]; })[0];\n  s.push({who:'bot', text: mine.length ? 'Совет: начните с «'+mine[0].title+'», это ближайший срок.' + (top ? ' Больше всего задач у '+({masha:'Маши',dima:'Димы',anya:'Ани',kostya:'Кости'}[top])+' ('+load[top]+'), не грузите сегодня новым.' : '') : 'Ваших задач нет, можно заняться стратегией.', btns:['Открыть доску','Отложить на 30 мин']});\n  return s;\n}\nfunction loadScene(autoplay){\n  var sc = SCENES[scnCur];\n  $('#scnTitle').textContent = sc.title; $('#scnSub').textContent = sc.sub;\n  var a = $('#scnAva'); a.textContent = sc.ava; a.classList.toggle('cat', sc.color==='cat'); a.style.background = sc.color==='cat' ? '' : sc.color;\n  $('#scnSide').innerHTML = sc.side + '<div class=\"scn-ctrl\"><button class=\"btn primary\" id=\"scnPlay\">Запустить</button><span class=\"small muted\" id=\"scnState\"></span></div>';\n  $('#scnPlay').addEventListener('click', function(){ playScene(); });\n  $('#msgs').innerHTML = '<div class=\"empty\" style=\"margin:auto\">Нажмите «Запустить»</div>';\n  if (autoplay) playScene();\n}\nfunction bubble(st, idx){\n  var el = document.createElement('div');\n  if (st.div){ el.className = 'divider'; el.textContent = st.div; return el; }\n  if (st.sys){ el.className = 'msg sys'; el.innerHTML = esc(st.sys) + btnsHtml(st.btns, idx); return el; }\n  var p = PEOPLE[st.who], out = st.who==='me';\n  el.className = 'msg' + (out ? ' out' : '') + (st.who==='bot' ? ' bot' : '');\n  var html = out ? '' : '<div class=\"who\" style=\"color:'+p.c+'\">'+esc(p.n)+'</div>';\n  if (st.voice){ var bars = ''; for (var i=0;i<34;i++){ bars += '<i style=\"height:'+(4+Math.round(Math.abs(Math.sin(i*1.7)+Math.sin(i*.6))*8))+'px\"></i>'; } html += '<div class=\"voice\"><span class=\"play\">▶</span><span class=\"wave\">'+bars+'</span><span class=\"small muted mono\">'+st.voice+'</span></div>'; }\n  if (st.text) html += esc(st.text);\n  if (st.card) html += '<div class=\"tcard\"><b>'+esc(st.card.t)+'</b><div class=\"meta\">'+st.card.m.map(esc).map(function(x){ return '<span>'+x+'</span>'; }).join('')+'</div></div>';\n  html += btnsHtml(st.btns, idx);\n  html += '<span class=\"tm\">'+clock(0)+'</span>';\n  el.innerHTML = html;\n  return el;\n}\nfunction btnsHtml(b, idx){ return b ? '<div class=\"ibtns\">'+b.map(function(x){ return '<button data-ib=\"'+esc(x)+'\">'+esc(x)+'</button>'; }).join('')+'</div>' : ''; }\n$('#msgs').addEventListener('click', function(e){\n  var b = e.target.closest('[data-ib]'); if (!b) return;\n  var lbl = b.getAttribute('data-ib'), row = b.parentNode;\n  if (lbl==='Открыть доску'){ location.hash = 'board'; return; }\n  row.innerHTML = '<span class=\"done\">Нажато: '+esc(lbl)+'</span>';\n});\nasync function playScene(){\n  var tok = ++scnTok, box = $('#msgs'), sc = SCENES[scnCur], script = sc.s || briefScript();\n  box.innerHTML = ''; $('#scnPlay').textContent = 'Заново'; $('#scnState').textContent = 'идёт сцена…';\n  for (var i=0;i<script.length;i++){\n    if (tok !== scnTok) return;\n    var st = script[i];\n    if (st.who==='bot' || st.sys){\n      var ty = document.createElement('div'); ty.className = 'typing'; ty.innerHTML = '<i></i><i></i><i></i>'; box.appendChild(ty); box.scrollTop = box.scrollHeight;\n      await sleep(reduce ? 0 : 750); if (tok !== scnTok) return; ty.remove();\n    }\n    box.appendChild(bubble(st, i)); box.scrollTop = box.scrollHeight;\n    await sleep(reduce ? 0 : (st.div ? 500 : 900 + Math.min(1200, (st.text||'').length*12)));\n  }\n  if (tok === scnTok) $('#scnState').textContent = 'сцена закончилась';\n}\nloadScene(false);\n\n/* ───────── 6. Память ───────── */\nvar KB, kbTab = 'me', kbAsFile = false, kbFlash = null;\nfunction seedKB(){\n  KB = {\n    me:[['Роль','Руководитель маркетинга, команда из 4 человек'],['Рабочие часы','10:00–19:00, после 21:00 не беспокоить'],['Формат отчётов',null],['Приоритеты квартала','Лиды из Директа, запуск вебинарной воронки'],['Как вы пишете','Коротко, на «ты» с командой, на «вы» с клиентами']],\n    project:[['Продукт','Онлайн-школа маркетинга'],['Бюджет ноября',null],['Ключевые метрики','CPL до 900 ₽, конверсия лендинга 4%'],['Подрядчики','Студия видео «Кадр», блогер @growth_lena'],['Клиенты в работе','ООО «Ромашка»: ждут КП']],\n    team:{masha:{tags:[['таргет'],['VK Ads, Директ']], st:null, rel:'85%'}, dima:{tags:[['дизайн'],['не любит частые пинги','w']], st:null, rel:'—'}, anya:{tags:[['SMM'],['контент-план по пятницам']], st:null, rel:'92%'}, kostya:{tags:[['продажи'],['тёплые лиды']], st:null, rel:'70%'}}\n  };\n}\nseedKB();\nvar FACTS = [\n  {from:'Маша в чате «Маркетинг»', text:'Ребят, я в отпуске с 20 по 27, на связи не буду', key:'masha', tab:'team', apply:function(){ KB.team.masha.st = 'Отпуск 20–27'; return 'masha'; }, impact:'Задачи Маши со сроком на эти даты ассистент предложит передать Ане или перенести. Напоминания Маше в отпуск не уйдут.'},\n  {from:'Вы, ассистенту в личку', text:'Отчёты собственнику делай по понедельникам: коротко, три цифры и выводы', key:'Формат отчётов', tab:'me', apply:function(){ KB.me[2][1] = 'По понедельникам, коротко: три цифры и выводы'; return 'Формат отчётов'; }, impact:'Отчёт собственнику в разделе «Вопросы к ИИ» теперь собирается в этом формате, и каждое утро понедельника приходит сам.'},\n  {from:'Чат «Маркетинг»', text:'Согласовали: бюджет на Директ в ноябре 400 тысяч', key:'Бюджет ноября', tab:'project', apply:function(){ KB.project[1][1] = 'Директ: 400 000 ₽'; return 'Бюджет ноября'; }, impact:'Ассистент будет сверять расход в дашборде с бюджетом и предупредит, если к 20-му числу потрачено больше 70%.'},\n  {from:'Статистика задач', text:'Дима закрыл 9 из 10 задач в срок за месяц', key:'dima', tab:'team', apply:function(){ KB.team.dima.rel = '90%'; KB.team.dima.tags.push(['надёжный','g']); return 'dima'; }, impact:'Диме хватает одного напоминания за сутки. Ассистент перестанет слать «за 2 часа», как он и любит.'},\n  {from:'Клиент в личке', text:'Нам удобно созваниваться только после 15:00', key:'Клиенты в работе', tab:'project', apply:function(){ KB.project[4][1] = 'ООО «Ромашка»: ждут КП, созвоны только после 15:00'; return 'Клиенты в работе'; }, impact:'Когда попросите назначить созвон с «Ромашкой», ассистент предложит только слоты после 15:00.'},\n  {from:'Костя в чате', text:'Я теперь веду ещё и партнёрские продажи', key:'kostya', tab:'team', apply:function(){ KB.team.kostya.tags.push(['партнёрки']); KB.team.kostya.st = 'Новая зона: партнёрки'; return 'kostya'; }, impact:'Задачи по партнёрам теперь автоматически уходят Косте. Ассистент заметит, если у него станет больше 6 открытых задач.'}\n];\nvar factUsed = {}, KBsrc = {};\nfunction factTarget(f){ return KB_TABS[f.tab]+' · '+(f.tab==='team' ? TEAM[f.key].name : f.key); }\nfunction renderFacts(){\n  $('#facts').innerHTML = FACTS.map(function(f,i){ return '<button class=\"fact'+(factUsed[i]?' used':'')+'\" data-fact=\"'+i+'\"'+(factUsed[i]?' disabled':'')+'><div class=\"ff\">'+esc(f.from)+'</div><div class=\"fx\">«'+esc(f.text)+'»</div><span class=\"fto\">'+(factUsed[i]?'✓ записано: ':'→ впишется в: ')+esc(factTarget(f))+'</span></button>'; }).join('') +\n    '<button class=\"btn sm\" id=\"factsReset\" style=\"align-self:flex-start\">Сбросить память</button>';\n}\n$('#facts').addEventListener('click', function(e){\n  if (e.target.closest('#factsReset')){ factUsed = {}; KBsrc = {}; seedKB(); kbFlash = null; $('#impact').hidden = true; renderFacts(); renderKB(); return; }\n  var b = e.target.closest('[data-fact]'); if (!b) return;\n  var i = +b.getAttribute('data-fact'), f = FACTS[i]; factUsed[i] = true;\n  kbFlash = f.apply(); kbTab = f.tab; KBsrc[f.key] = f.from;\n  $$('#kbTabs button').forEach(function(x){ x.classList.toggle('on', x.getAttribute('data-kb')===kbTab); });\n  var im = $('#impact'); im.hidden = false; im.innerHTML = '<b>Что изменится</b>'+esc(f.impact);\n  renderFacts(); renderKB();\n});\nvar KB_TABS = {me:'О вас', project:'Проект', team:'Команда'};\n$('#kbTabs').innerHTML = Object.keys(KB_TABS).map(function(k){ return '<button data-kb=\"'+k+'\" class=\"'+(k===kbTab?'on':'')+'\">'+KB_TABS[k]+'</button>'; }).join('');\n$('#kbTabs').addEventListener('click', function(e){ var b = e.target.closest('[data-kb]'); if (!b) return; kbTab = b.getAttribute('data-kb'); kbFlash = null; $$('#kbTabs button').forEach(function(x){ x.classList.toggle('on', x===b); }); renderKB(); });\n$('#kbFile').addEventListener('click', function(){ kbAsFile = !kbAsFile; this.textContent = kbAsFile ? 'Показать карточками' : 'Показать как файл скилла'; renderKB(); });\nfunction kbFileText(){\n  var name = {me:'about-me.md', project:'project.md', team:'team.md'}[kbTab];\n  var s = '# '+name+'\\n# Обновляет ассистент. Последняя правка: '+fmt(sim)+'\\n\\n';\n  if (kbTab==='team'){\n    Object.keys(KB.team).forEach(function(id){ var p = KB.team[id]; s += '## '+TEAM[id].name+' — '+TEAM[id].role+'\\n- Сроки соблюдает: '+p.rel+'\\n- Метки: '+p.tags.map(function(x){ return x[0]; }).join(', ')+'\\n'+(p.st ? '- Сейчас: '+p.st+'\\n' : '')+'\\n'; });\n  } else {\n    KB[kbTab].forEach(function(r){ s += '## '+r[0]+'\\n'+(r[1] || '(пока неизвестно)')+'\\n\\n'; });\n  }\n  return s.trim();\n}\nfunction renderKB(){\n  var b = $('#kbBody');\n  if (kbAsFile){ b.innerHTML = '<pre class=\"file\" style=\"padding-top:8px\">'+esc(kbFileText())+'</pre>'; return; }\n  if (kbTab==='team'){\n    b.innerHTML = Object.keys(KB.team).map(function(id){\n      var p = KB.team[id], t = TEAM[id];\n      return '<div class=\"person'+(kbFlash===id?' flash':'')+'\" data-k=\"'+id+'\"><div class=\"ava\" style=\"background:'+t.color+'\">'+esc(t.name[0])+'</div><div><div class=\"pn\">'+esc(t.name)+' <span class=\"small muted\" style=\"font-weight:400\">· '+esc(t.role)+'</span></div><div class=\"pr\">Сроки соблюдает: <span class=\"mono\">'+p.rel+'</span>'+(KBsrc[id]?'<span class=\"src-from\">← из: '+esc(KBsrc[id])+'</span>':'')+'</div><div class=\"tags\">'+(p.st?'<span class=\"tag w\">'+esc(p.st)+'</span>':'')+p.tags.map(function(x){ return '<span class=\"tag '+(x[1]||'')+'\">'+esc(x[0])+'</span>'; }).join('')+'</div></div></div>';\n    }).join('');\n  } else {\n    b.innerHTML = KB[kbTab].map(function(r){ return '<div class=\"kv'+(kbFlash===r[0]?' flash':'')+'\" data-k=\"'+esc(r[0])+'\"><b>'+esc(r[0])+'</b><span'+(r[1]?'':' class=\"nil\"')+'>'+esc(r[1]||'пока неизвестно')+(KBsrc[r[0]]?'<span class=\"src-from\">← из: '+esc(KBsrc[r[0]])+'</span>':'')+'</span></div>'; }).join('');\n  }\n  requestAnimationFrame(drawLinks);\n}\nvar hoverFact = null;\nfunction drawLinks(){\n  var svg = $('#memLinks'), mem = $('#mem');\n  if (!svg || window.innerWidth < 900 || kbAsFile){ if (svg) svg.innerHTML = ''; return; }\n  var box = mem.getBoundingClientRect(), out = '';\n  function line(i, hint){\n    var f = FACTS[i], fb = $('#facts [data-fact=\"'+i+'\"]'), tg = $('#kbBody [data-k=\"'+f.key+'\"]');\n    if (!fb || !tg || f.tab !== kbTab) return;\n    var a = fb.getBoundingClientRect(), b = tg.getBoundingClientRect();\n    var x1 = a.right - box.left, y1 = a.top + a.height/2 - box.top, x2 = b.left - box.left - 4, y2 = b.top + Math.min(b.height/2, 18) - box.top, mx = (x1+x2)/2;\n    var c = hint ? ' class=\"hint\"' : '';\n    out += '<path'+c+' d=\"M'+x1+' '+y1+' C'+mx+' '+y1+' '+mx+' '+y2+' '+x2+' '+y2+'\"/><circle'+c+' cx=\"'+x1+'\" cy=\"'+y1+'\" r=\"4\"/><circle'+c+' cx=\"'+x2+'\" cy=\"'+y2+'\" r=\"4\"/>';\n  }\n  FACTS.forEach(function(f,i){ if (factUsed[i]) line(i, false); });\n  if (hoverFact !== null && !factUsed[hoverFact]) line(hoverFact, true);\n  svg.innerHTML = out;\n}\nwindow.addEventListener('resize', function(){ requestAnimationFrame(drawLinks); });\n$('#facts').addEventListener('mouseover', function(e){\n  var b = e.target.closest('[data-fact]'); var i = b ? +b.getAttribute('data-fact') : null;\n  if (i === hoverFact) return; hoverFact = i;\n  $$('#kbTabs button').forEach(function(x){ x.classList.toggle('hint', i!==null && !factUsed[i] && FACTS[i].tab===x.getAttribute('data-kb') && FACTS[i].tab!==kbTab); });\n  drawLinks();\n});\n$('#facts').addEventListener('mouseleave', function(){ hoverFact = null; $$('#kbTabs button').forEach(function(x){ x.classList.remove('hint'); }); drawLinks(); });\nrenderFacts(); renderKB();\n\n/* ───────── 7. Вопросы к ИИ ───────── */\nvar GEN = {me:'вас', masha:'Маши', dima:'Димы', anya:'Ани', kostya:'Кости'};\nfunction li(arr){ return '<ul>'+arr.map(function(x){ return '<li>'+x+'</li>'; }).join('')+'</ul>'; }\nfunction tline(t,h){ return '«'+esc(t.title)+'» · '+esc(TEAM[t.who].name)+' · '+esc(relDue(t.due,h).t); }\nvar QUESTIONS = [\n  {q:'Что горит сегодня и завтра?', kw:/гор|сегодня|завтра|срочн/i, fn:function(h){\n    var open = tasks.filter(function(t){ return isOpen(t,h); });\n    var over = open.filter(function(t){ return t.due<h; }).sort(function(a,b){ return a.due-b.due; });\n    var soon = open.filter(function(t){ return t.due>=h && dayIdx(t.due)-dayIdx(h)<=1; }).sort(function(a,b){ return a.due-b.due; });\n    var out = [];\n    out.push(over.length ? '<h4>Уже просрочено: '+over.length+'</h4>'+li(over.map(function(t){ return tline(t,h); })) : '<h4>Просрочек нет</h4>');\n    out.push(soon.length ? '<h4>Срок сегодня и завтра: '+soon.length+'</h4>'+li(soon.map(function(t){ return tline(t,h); })) : '<p>На сегодня и завтра сроков больше нет.</p>');\n    if (over.length) out.push('<p>Начал бы с «'+esc(over[0].title)+'»: она висит дольше всех.</p>');\n    return out; }},\n  {q:'Кто сейчас перегружен?', kw:/перегруж|загруж|загрузк|кто/i, fn:function(h){\n    var load = {}; TEAM_IDS.forEach(function(id){ load[id] = {o:0, x:0}; });\n    tasks.forEach(function(t){ if (isOpen(t,h)){ load[t.who].o++; if (t.due<h) load[t.who].x++; } });\n    var ids = TEAM_IDS.slice().sort(function(a,b){ return (load[b].o+load[b].x*2)-(load[a].o+load[a].x*2); });\n    var top = ids[0], free = ids[ids.length-1]===('me') ? ids[ids.length-2] : ids[ids.length-1];\n    return ['<h4>Открытые задачи по людям</h4>'+li(ids.map(function(id){ return esc(TEAM[id].name)+': <span class=\"mono\">'+load[id].o+'</span> открыто'+(load[id].x ? ', <b style=\"color:var(--bad)\">'+load[id].x+' просрочено</b>' : ''); })),\n      '<p>Тяжелее всего сейчас у '+GEN[top]+'. '+(load[top].x ? 'Есть просрочки, поэтому новые задачи лучше отдать '+(free==='me'?'себе':TEAM[free].name.replace(/а$/,'е').replace(/я$/,'е'))+'.' : 'Просрочек пока нет, но новое лучше не добавлять.')+'</p>']; }},\n  {q:'Что я пообещал и ещё не сделал?', kw:/обещ|пообещ|я должен|мои/i, fn:function(h){\n    var mine = tasks.filter(function(t){ return t.who==='me' && isOpen(t,h); }).sort(function(a,b){ return a.due-b.due; });\n    if (!mine.length) return ['<p>Все ваши обещания закрыты. Красиво.</p>'];\n    var ext = mine.filter(function(t){ return t.src==='biz'||t.src==='mail'; });\n    return ['<h4>Ваши открытые задачи: '+mine.length+'</h4>'+li(mine.map(function(t){ return '«'+esc(t.title)+'» · '+srcBadge(t.src)+' · '+esc(relDue(t.due,h).t); })),\n      ext.length ? '<p>Из них '+ext.length+' '+plural(ext.length,'обещание','обещания','обещаний')+' внешним людям: клиентам и подрядчикам. Их стоит закрыть первыми, это ваша репутация.</p>' : ''].filter(Boolean); }},\n  {q:'Сделай отчёт собственнику за неделю', kw:/отч[её]т|собственник|итог/i, fn:function(h){\n    var from = Math.max(0, h-168), vis = tasks.filter(function(t){ return statusAt(t,h); });\n    var done = vis.filter(function(t){ return t.doneAt!==null && t.doneAt<=h && t.doneAt>=from; });\n    var ok = done.filter(function(t){ return t.doneAt<=t.due; }).length;\n    var over = vis.filter(function(t){ return isOpen(t,h) && t.due<h; });\n    var short = !!factUsed[1];\n    var head = '<p class=\"q\">'+(short ? 'Формат из памяти: три цифры и выводы' : 'Формат не задан, делаю подробно. Совет: скажите мне, как вы любите, в разделе «Память»')+'</p>';\n    var nums = li(['Закрыто задач: <b class=\"mono\">'+done.length+'</b>', 'В срок: <b class=\"mono\">'+(done.length?Math.round(ok/done.length*100):0)+'%</b>', 'Висит просроченных: <b class=\"mono\">'+over.length+'</b>']);\n    var concl = '<h4>Выводы</h4>'+li([\n      done.length ? 'Закрыли: '+done.slice(0,3).map(function(t){ return '«'+esc(t.title)+'»'; }).join(', ')+(done.length>3?' и ещё '+(done.length-3):'')+'.' : 'Пока ничего не закрыто, сдвиньте время на доске.',\n      over.length ? 'Риск: '+over.slice(0,2).map(function(t){ return '«'+esc(t.title)+'» у '+GEN[t.who]; }).join(', ')+'.' : 'Рисков по срокам нет.',\n      factUsed[2] ? 'Бюджет Директа на ноябрь 400 000 ₽ согласован.' : 'Реклама: ретаргет на корзины запущен, CPL держим в цели.'\n    ]);\n    if (short) return [head, nums, concl];\n    var by = {}; done.forEach(function(t){ by[t.who] = (by[t.who]||0)+1; });\n    return [head, '<h4>Цифры недели</h4>'+nums, '<h4>Кто что закрыл</h4>'+li(Object.keys(by).length ? Object.keys(by).map(function(id){ return esc(TEAM[id].name)+': '+by[id]; }) : ['пока никто']), concl]; }},\n  {q:'Почему просрочки и что с ними делать?', kw:/просроч|почему|сорв/i, fn:function(h){\n    var over = tasks.filter(function(t){ return isOpen(t,h) && t.due<h; }).sort(function(a,b){ return a.due-b.due; });\n    if (!over.length) return ['<p>Просрочек нет. Подвиньте время на доске вперёд, Костя скоро что-нибудь сорвёт.</p>'];\n    var ev = allEvents().filter(function(e){ return e.t<=h && e.task; });\n    return ['<h4>Просрочено: '+over.length+'</h4>'+li(over.map(function(t){\n      var n = ev.filter(function(e){ return e.task===t && e.to===t.who; }).length;\n      var why = t.who==='me' ? 'это ваша задача, напоминания приходили вам' : (n>=2 ? TEAM[t.who].name+' не ответил(а) на '+n+' '+plural(n,'напоминание','напоминания','напоминаний')+', похоже, не хватает времени' : 'напоминание ушло, ответа пока нет');\n      return '«'+esc(t.title)+'» · '+esc(relDue(t.due,h).t)+'<br><span class=\"muted\">'+esc(why)+'</span>';\n    })), '<p>Что предлагаю: '+(over.some(function(t){ return t.who==='kostya'; }) ? 'у Кости обзвон на 23 контакта, это 2 дня работы. Разбейте на две части или отдайте половину Ане.' : 'назначьте новые сроки одной кнопкой в карточке, ассистент предупредит всех, кого это касается.')+'</p>']; }},\n  {q:'Что по клиенту «Ромашка»?', kw:/ромашк|клиент|иван/i, fn:function(h){\n    var t = tasks.filter(function(x){ return /Ромашк/.test(x.title); })[0];\n    var st = t ? statusAt(t,h) : null;\n    return ['<h4>ООО «Ромашка», контакт Иван Петров</h4>', li([\n      'Запросили КП и кейсы, вы пообещали в личке.',\n      t ? 'Задача «'+esc(t.title)+'»: '+(st==='done' ? 'готово' : esc(relDue(t.due,h).t)) : 'Задачи нет.',\n      factUsed[4] ? 'Созвоны только после 15:00 (из переписки).' : 'Предпочтений по времени пока не знаю.',\n      'Последнее касание: личка, '+fmt(Math.max(0,h-20))+'.'\n    ]), '<p>'+(st==='done' ? 'Следующий шаг: через 2 дня спросить, что сказал директор. Поставить напоминание?' : 'Черновик КП можно собрать из шаблона и двух кейсов из похожей ниши. Подготовить?')+'</p>']; }},\n  {q:'Как реклама связана с задачами?', kw:/реклам|директ|cpl|дашборд|метрик/i, fn:function(h){\n    var ads = tasks.filter(function(t){ return t.proj==='Реклама' && statusAt(t,h); });\n    return ['<h4>Реклама: задачи рядом с цифрами</h4>'+li(ads.map(function(t){ var s = statusAt(t,h); return '«'+esc(t.title)+'» · '+esc(TEAM[t.who].name)+' · '+(s==='done'?'готово':esc(relDue(t.due,h).t)); })),\n      '<p>'+(firedRules.cpl ? 'CPL в Директе вырос на 38%, поэтому я поставил Маше задачу проверить кампании.' : 'Метрики дашборда в норме. Если CPL уйдёт выше порога, задача Маше появится сама, попробуйте в разделе 8.')+(factUsed[2] ? ' Бюджет ноября на Директ: 400 000 ₽.' : '')+'</p>']; }}\n];\n$('#qs').innerHTML = QUESTIONS.map(function(q,i){ return '<button class=\"chip\" data-q=\"'+i+'\">'+esc(q.q)+'</button>'; }).join('');\nvar askTok = 0;\nasync function answer(i, asked){\n  var tok = ++askTok, q = QUESTIONS[i], out = $('#askOut');\n  $$('#qs .chip').forEach(function(c){ c.classList.toggle('on', +c.getAttribute('data-q')===i); });\n  out.innerHTML = '<p class=\"q\">Вопрос: '+esc(asked || q.q)+' · данные на '+fmt(sim)+'</p><div class=\"typing\" style=\"display:inline-flex\"><i></i><i></i><i></i></div>';\n  await sleep(reduce?0:650); if (tok!==askTok) return;\n  out.innerHTML = '<p class=\"q\">Вопрос: '+esc(asked || q.q)+' · данные на '+fmt(sim)+'</p>';\n  var parts = q.fn(sim);\n  for (var k=0;k<parts.length;k++){ if (tok!==askTok) return; var d = document.createElement('div'); d.innerHTML = parts[k]; out.appendChild(d); await sleep(reduce?0:220); }\n}\n$('#qs').addEventListener('click', function(e){ var b = e.target.closest('[data-q]'); if (b) answer(+b.getAttribute('data-q')); });\n$('#askForm').addEventListener('submit', function(e){\n  e.preventDefault(); var v = $('#askIn').value.trim(); if (!v) return;\n  var idx = -1; QUESTIONS.forEach(function(q,i){ if (idx<0 && q.kw.test(v)) idx = i; });\n  $('#askIn').value = '';\n  if (idx>=0) { answer(idx, v); return; }\n  ++askTok; $$('#qs .chip').forEach(function(c){ c.classList.remove('on'); });\n  $('#askOut').innerHTML = '<p class=\"q\">Вопрос: '+esc(v)+'</p><p>В настоящей системе на это ответит Claude: у него будут все задачи, переписка и база знаний. В демо я понимаю вопросы про сроки, загрузку, обещания, отчёт, просрочки, клиента «Ромашка» и рекламу.</p>';\n});\n\n/* ───────── 8. Триггеры из дашборда и CRM ───────── */\nvar RULES = [\n  {id:'cpl', src:'dash', ifT:'CPL в Директе вырос больше чем на 30% за 3 дня', base:[820,790,840,810,860,830,850], spike:[980,1090,1140], unit:'₽', thenT:'Маше: проверить кампании и ставки, срок сегодня 18:00', task:['Проверить кампании Директа: CPL +38% за 3 дня','masha','Реклама',8]},\n  {id:'lead', src:'crm', ifT:'Новый лид в CRM без ответа больше 2 часов', base:[0.4,0.6,0.3,0.5,0.4,0.7,0.5], spike:[1.2,2.1,2.6], unit:'ч', thenT:'Косте: связаться с лидом. Через 4 часа без ответа пишу вам', task:['Перезвонить лиду с сайта: ждёт ответа 2,5 часа','kostya','Продажи',1]},\n  {id:'deal', src:'crm', ifT:'Сделка без движения 7 дней', base:[1,2,3,1,2,2,3], spike:[5,6,7], unit:'дн', thenT:'Менеджеру: следующий шаг по сделке, вам в пятничную сводку', task:['Сделка «ТехноПарк»: 7 дней без движения, предложить встречу','kostya','Продажи',6]},\n  {id:'conv', src:'dash', ifT:'Конверсия лендинга упала ниже 3%', base:[4.1,4.3,3.9,4.2,4.0,4.4,4.1], spike:[3.4,2.9,2.6], unit:'%', thenT:'Диме: проверить лендинг после обновления баннера, вам в известность', task:['Конверсия лендинга упала до 2,6%: проверить после обновления','dima','Креативы',5]},\n  {id:'post', src:'tg', ifT:'Пост из контент-плана не вышел в срок', base:[1,1,1,1,1,1,1], spike:[1,0,0], unit:'', thenT:'Ане: опубликовать или перенести, в общий чат только если молчит сутки', task:['Пост «Итоги вебинара» не вышел по плану','anya','Контент',3]}\n];\nvar firedRules = {};\nfunction spark(vals, hot){\n  var w = 130, ht = 36, mn = Math.min.apply(null, vals), mx = Math.max.apply(null, vals), rg = (mx-mn)||1;\n  var pts = vals.map(function(v,i){ return [Math.round(i/(vals.length-1)*w*10)/10, Math.round((ht-3-(v-mn)/rg*(ht-6))*10)/10]; });\n  var line = pts.map(function(p){ return p.join(','); }).join(' ');\n  var last = pts[pts.length-1];\n  return '<svg viewBox=\"0 0 130 40\" aria-hidden=\"true\"><polyline points=\"'+line+'\" fill=\"none\" stroke=\"'+(hot?'var(--bad)':'var(--ink-3)')+'\" stroke-width=\"1.8\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><circle cx=\"'+last[0]+'\" cy=\"'+last[1]+'\" r=\"3\" fill=\"'+(hot?'var(--bad)':'var(--ink-3)')+'\"/></svg>';\n}\nfunction renderRules(){\n  $('#rules').innerHTML = RULES.map(function(r){\n    var f = firedRules[r.id];\n    var vals = f ? r.base.slice(3).concat(r.spike) : r.base;\n    return '<div class=\"card rule'+(f?' fired':'')+'\"><div class=\"if\"><b>Если '+srcBadge(r.src)+'</b>'+esc(r.ifT)+'</div>'+spark(vals, !!f)+'<div class=\"then\"><b>То</b>'+esc(r.thenT)+'</div><button class=\"btn sm'+(f?'':' primary')+'\" data-rule=\"'+r.id+'\"'+(f?' disabled':'')+'>'+(f?'Сработало':'Попробовать')+'</button>'+(f?'<div class=\"res\">Задача на доске: «'+esc(r.task[0])+'», '+esc(TEAM[r.task[1]].name)+', срок '+esc(fmt(f.due))+'. <a href=\"#board\">Смотреть</a></div>':'')+'</div>';\n  }).join('');\n}\n$('#rules').addEventListener('click', function(e){\n  var b = e.target.closest('[data-rule]'); if (!b) return;\n  var r = RULES.filter(function(x){ return x.id===b.getAttribute('data-rule'); })[0];\n  var t = addTask(r.task[0], r.task[1], sim + r.task[3], r.src, r.task[2]);\n  firedRules[r.id] = t; renderRules();\n  toast('Триггер сработал: задача у '+esc(GEN[r.task[1]])+' · <a href=\"#board\">на доску</a>');\n});\nrenderRules();\n\n/* ───────── 9. Идеи ───────── */\nvar IDEAS = [\n  {id:'promise', t:'Детектор обещаний', d:'Ловит ваши «скину завтра» и «гляну вечером» в любых чатах и ставит вам задачу, чтобы вы не стали тем, кто обещает и пропадает.', fx:3, cx:1},\n  {id:'protocol', t:'Протокол созвона', d:'После Zoom или Meet присылает итоги, решения и задачи с исполнителями. Каждому участнику только его часть.', fx:3, cx:2},\n  {id:'standup', t:'Стендап в чате', d:'В 10:00 бот спрашивает каждого «что сегодня и что мешает», а в 10:30 присылает вам сводку и блокеры.', fx:2, cx:1},\n  {id:'load', t:'Индекс загрузки', d:'Видит, у кого больше всего открытых задач и просрочек, и предлагает перераспределить новую задачу.', fx:2, cx:2},\n  {id:'vacation', t:'Режим отпуска', d:'Передаёт задачи заместителю, отвечает за вас «я в отпуске до 27-го, по срочному к Ане» и собирает дайджест к возвращению.', fx:2, cx:1},\n  {id:'drafts', t:'Черновики ответов', d:'Готовит ответ клиенту вашим стилем по базе знаний. Вы только проверяете и жмёте «Отправить».', fx:3, cx:2},\n  {id:'forgot', t:'«Что я забыл?»', d:'Раз в неделю ищет в переписке хвосты, по которым нет задачи: вопросы без ответа, обещания без даты.', fx:3, cx:2},\n  {id:'retro', t:'Пятничная ретро', d:'Итоги недели в общий чат: что сделали, что сорвали и почему. Без поиска виноватых, с цифрами.', fx:2, cx:1},\n  {id:'leader', t:'Лидерборд «в срок»', d:'Очки за задачи, закрытые вовремя. Раз в неделю рейтинг в чате и символический приз лучшему.', fx:1, cx:1},\n  {id:'onboard', t:'Онбординг новичка', d:'Новый сотрудник спрашивает бота, где лежит бриф и кто отвечает за Директ. Бот отвечает по базе знаний.', fx:2, cx:2},\n  {id:'vendors', t:'Контроль подрядчиков', d:'Внешние исполнители получают задачи и напоминания в своей личке, а вы видите их сроки на общей доске.', fx:2, cx:1},\n  {id:'mood', t:'Пульс команды', d:'По тону сообщений замечает усталость и раздражение, тихо подсказывает вам, с кем стоит поговорить.', fx:2, cx:3}\n];\nvar ideaOn = {promise:true};\nfunction renderIdeas(){\n  $('#ideaGrid').innerHTML = IDEAS.map(function(it){\n    return '<button class=\"idea'+(ideaOn[it.id]?' on':'')+'\" data-idea=\"'+it.id+'\" aria-pressed=\"'+(!!ideaOn[it.id])+'\"><h3>'+esc(it.t)+'</h3><p>'+esc(it.d)+'</p><div class=\"im\"><span>эффект <span class=\"dots\">'+'●'.repeat(it.fx)+'○'.repeat(3-it.fx)+'</span> · сложность <span class=\"dots\">'+'●'.repeat(it.cx)+'○'.repeat(3-it.cx)+'</span></span><span class=\"add\">'+(ideaOn[it.id]?'в системе':'+ добавить')+'</span></div></button>';\n  }).join('');\n}\n$('#ideaGrid').addEventListener('click', function(e){ var b = e.target.closest('[data-idea]'); if (!b) return; var id = b.getAttribute('data-idea'); ideaOn[id] = !ideaOn[id]; renderIdeas(); renderBuild(); });\nrenderIdeas();\n\n/* ───────── 10. Конструктор ───────── */\nvar MODS = [\n  {g:'Источники', items:[\n    {id:'tg', t:'Бот в рабочих чатах', d:1, need:['Токен бота из BotFather','Сервис расшифровки речи'], on:true},\n    {id:'biz', t:'ТГ Business-бот в личке', d:1, need:['Telegram Premium','Подключение бота в Telegram для бизнеса','Сервис расшифровки речи']},\n    {id:'mail', t:'Почта', d:1, need:['Google OAuth (Gmail API)']},\n    {id:'cal', t:'Календарь', d:.5, need:['Google OAuth (Calendar API)']},\n    {id:'crm', t:'CRM', d:1, need:['API-ключ и вебхуки CRM']},\n    {id:'voice', t:'Созвоны в Zoom', d:1, need:['Zoom API (записи созвонов)']},\n    {id:'dash', t:'Дашборд маркетинга', d:.5, need:['Доступ к data.json дашборда']}\n  ]},\n  {g:'OS', items:[\n    {id:'tasks', t:'Задачи и сроки', d:2, need:['Ключ Claude API','Аккаунт Cloudflare (Worker + KV)'], on:true, lock:true},\n    {id:'remind', t:'Напоминания и эскалации', d:1, need:[], on:true},\n    {id:'kb', t:'База знаний и память', d:1, need:[]}\n  ]},\n  {g:'Интерфейсы', items:[\n    {id:'web', t:'Таск-трекер (веб)', d:2, need:['Пароль для входа'], on:true},\n    {id:'ask', t:'Вопросы к ИИ', d:1, need:[]},\n    {id:'reports', t:'Отчёты', d:.5, need:[]},\n    {id:'brief', t:'Утренний брифинг', d:.5, need:[], on:true}\n  ]}\n];\nvar ACCESS = {\n  'Токен бота из BotFather':[\n    'В Telegram откройте <b>@BotFather</b> и отправьте <code>/newbot</code>.',\n    'Задайте имя бота и username, он должен заканчиваться на <code>bot</code>.',\n    'BotFather пришлёт токен вида <code>123456789:AA…</code>. Это пароль от бота, никому его не пересылайте.',\n    'Положите токен в секрет воркера: <code>wrangler secret put BOT_TOKEN</code>.',\n    'Чтобы бот видел все сообщения в группах: <code>/setprivacy</code> → ваш бот → <b>Disable</b>.',\n    'Если токен утёк: <code>/revoke</code> в BotFather выдаст новый.'\n  ],\n  'Telegram Premium':[\n    'Нужен на <b>вашем</b> аккаунте, где идёт переписка с клиентами, а не на боте.',\n    'Telegram → Настройки → Telegram Premium → оформить подписку.',\n    'После оплаты в настройках появится раздел «Telegram для бизнеса».'\n  ],\n  'Подключение бота в Telegram для бизнеса':[\n    '<b>@BotFather</b> → <code>/mybots</code> → ваш бот → Bot Settings → <b>Business Mode</b> → Turn on.',\n    'В Telegram: Настройки → Telegram для бизнеса → <b>Чат-боты</b>.',\n    'Введите username бота и подтвердите.',\n    'Выберите доступ: «Все чаты, кроме…» или «Только выбранные». Личные переписки исключите.',\n    'Галочку «Отвечать на сообщения» ставьте, только если хотите, чтобы бот мог писать от вашего имени.'\n  ],\n  'Google OAuth (Gmail API)':[\n    'Откройте <b>console.cloud.google.com</b> и создайте проект, например «Ассистент».',\n    'APIs &amp; Services → Library → <b>Gmail API</b> → Enable.',\n    'OAuth consent screen: тип External (или Internal для Google Workspace), добавьте свой email в тестовые пользователи.',\n    'Credentials → Create credentials → <b>OAuth client ID</b> → Web application. В Authorized redirect URIs укажите <code>https://&lt;ваш воркер&gt;/oauth/google</code>.',\n    'Client ID и Client secret в секреты: <code>wrangler secret put GOOGLE_CLIENT_ID</code> и <code>GOOGLE_CLIENT_SECRET</code>.',\n    'Откройте <code>/oauth/google</code> на воркере, войдите и разрешите доступ к почте. Воркер сохранит доступ и дальше будет читать письма сам.'\n  ],\n  'Google OAuth (Calendar API)':[\n    'В том же проекте Google Cloud: Library → <b>Google Calendar API</b> → Enable.',\n    'На экране согласия добавьте доступ <code>calendar.readonly</code> (или к событиям, если ассистент будет сам ставить встречи).',\n    'Ещё раз откройте <code>/oauth/google</code> на воркере и подтвердите новый доступ.'\n  ],\n  'API-ключ и вебхуки CRM':[\n    '<b>amoCRM:</b> Настройки → Интеграции → Создать интеграцию → Внешняя интеграция. После установки на вкладке «Ключи и доступы» сгенерируйте долгосрочный токен.',\n    'amoCRM, вебхуки: Настройки → Интеграции → Web hooks → адрес <code>https://&lt;воркер&gt;/crm-hook</code>, события: сделка добавлена, смена этапа, примечание.',\n    '<b>Bitrix24:</b> Приложения → Разработчикам → Другое → <b>Входящий вебхук</b>, права «CRM». Скопируйте адрес с ключом. Для событий там же создайте исходящий вебхук.',\n    'Токен или адрес вебхука в секрет: <code>wrangler secret put CRM_TOKEN</code>.',\n    'Нужны права администратора CRM.'\n  ],\n  'Zoom API (записи созвонов)':[\n    'Нужен платный тариф Zoom с облачной записью и права администратора аккаунта.',\n    '<b>marketplace.zoom.us</b> → Develop → Build App → <b>Server-to-Server OAuth</b>.',\n    'Скопируйте Account ID, Client ID и Client Secret в секреты воркера.',\n    'Scopes: добавьте чтение облачных записей (раздел Recording).',\n    'Feature → Event Subscriptions → адрес воркера и событие «All Recordings have completed». Secret Token тоже в секрет, по нему воркер проверяет запросы.',\n    'Нажмите Activate. В настройках Zoom включите облачную запись и Audio transcript.'\n  ],\n  'Сервис расшифровки речи':[\n    '<b>Проще всего — Workers AI на том же Cloudflare:</b> в <code>wrangler.toml</code> добавьте <code>[ai] binding = \"AI\"</code> и вызывайте модель Whisper. Отдельный ключ не нужен.',\n    '<b>Или Yandex SpeechKit:</b> Yandex Cloud → сервисный аккаунт с ролью для распознавания речи → API-ключ → <code>wrangler secret put STT_KEY</code>.',\n    'Голосовые из Telegram бот скачивает через <code>getFile</code> и отправляет в выбранный сервис.'\n  ],\n  'Доступ к data.json дашборда':[\n    'Если дашборд на этом же воркере, отдельный доступ не нужен: данные лежат в <code>/dashboard/data.json</code>.',\n    'Если дашборд на другом воркере: подключите его через service binding в <code>wrangler.toml</code> или откройте адрес с токеном в секрете.'\n  ],\n  'Ключ Claude API':[\n    'Откройте <b>console.anthropic.com</b> и войдите.',\n    'Billing: пополните баланс. В Limits поставьте месячный лимит расходов.',\n    'API Keys → <b>Create Key</b>, назовите «Ассистент» и скопируйте ключ: он показывается один раз.',\n    'Положите в секрет воркера: <code>wrangler secret put CLAUDE_API</code>.'\n  ],\n  'Аккаунт Cloudflare (Worker + KV)':[\n    'Зарегистрируйтесь на <b>dash.cloudflare.com</b>. Для старта хватает бесплатного плана, cron-триггеры в нём тоже есть.',\n    'Установите wrangler: <code>npm i -g wrangler</code>, затем <code>wrangler login</code>.',\n    'Создайте хранилище: <code>wrangler kv namespace create TASKS</code> и впишите выданный id в <code>wrangler.toml</code>.',\n    'Деплой: <code>wrangler deploy</code>. Адрес воркера появится в выводе команды.'\n  ],\n  'Пароль для входа':[\n    'Придумайте пароль для таск-трекера.',\n    'Положите в секрет: <code>wrangler secret put ADMIN_PASSWORD</code>.',\n    'Если нужны отдельные входы для сотрудников, сделайте логины и роли, как в CRM лички.'\n  ]\n};\nvar modOn = {};\nMODS.forEach(function(g){ g.items.forEach(function(m){ if (m.on) modOn[m.id] = true; }); });\nfunction renderMods(){\n  $('#mods').innerHTML = MODS.map(function(g){\n    return '<h4>'+g.g+'</h4>'+g.items.map(function(m){ return '<label class=\"mod\"><input type=\"checkbox\" id=\"mod-'+m.id+'\" data-mod=\"'+m.id+'\"'+(modOn[m.id]?' checked':'')+(m.lock?' disabled':'')+'>'+esc(m.t)+(m.lock?' <span class=\"small muted\">обязательно</span>':'')+'</label>'; }).join('');\n  }).join('') + '<h4>Идеи из раздела 9</h4><div class=\"small muted\" id=\"modIdeas\"></div>';\n}\n$('#mods').addEventListener('change', function(e){ var c = e.target.closest('[data-mod]'); if (!c) return; modOn[c.getAttribute('data-mod')] = c.checked; renderBuild(); });\nfunction renderBuild(){\n  var sel = []; MODS.forEach(function(g){ g.items.forEach(function(m){ if (modOn[m.id]) sel.push(m); }); });\n  var ideas = IDEAS.filter(function(i){ return ideaOn[i.id]; });\n  $('#modIdeas').innerHTML = ideas.length ? ideas.map(function(i){ return esc(i.t); }).join(', ') + '' : 'Не выбраны. <a href=\"#ideas\">Выбрать</a>';\n  var days = sel.reduce(function(a,m){ return a+m.d; }, 0) + ideas.reduce(function(a,i){ return a+i.cx*.5; }, 0);\n  var need = []; sel.forEach(function(m){ m.need.forEach(function(n){ if (need.indexOf(n)<0) need.push(n); }); });\n  if (ideas.some(function(i){ return i.id==='protocol'; }) && need.indexOf('Сервис расшифровки речи')<0) need.push('Сервис расшифровки речи');\n  var has = function(id){ return !!modOn[id]; };\n  var srcs = ['tg','biz','mail','cal','crm','voice','dash'].filter(has);\n  var phases = [];\n  phases.push({t:'Этап 1 · MVP', d:'Задачи и сроки'+(has('tg')?', бот в рабочих чатах':'')+(has('remind')?', напоминания':'')+'. Цель: одна команда неделю живёт с ботом.'});\n  var p2 = srcs.filter(function(s){ return s!=='tg'; }).map(function(s){ return NODES[s].t; });\n  if (p2.length || has('kb')) phases.push({t:'Этап 2 · Больше источников', d:(p2.length ? 'Подключаем: '+p2.join(', ')+'. ' : '')+(has('kb') ? 'Включаем базу знаний, чтобы ассистент копил факты.' : '')});\n  var ui = ['web','ask','reports','brief'].filter(has).map(function(id){ return {web:'таск-трекер',ask:'вопросы к ИИ',reports:'отчёты',brief:'утренний брифинг'}[id]; });\n  if (ui.length) phases.push({t:'Этап 3 · Интерфейсы', d:'Делаем '+ui.join(', ')+'.'});\n  if (ideas.length) phases.push({t:'Этап 4 · Фишки', d:ideas.map(function(i){ return i.t; }).join(', ')+'.'});\n  var prompt = 'Собери ИИ-ассистента для задач команды на Cloudflare Worker + KV.\\n\\n'+\n    'Источники: '+(srcs.length ? srcs.map(function(s){ return NODES[s].t; }).join(', ') : 'только ручной ввод')+'.\\n'+\n    'OS: разбор сообщений в задачи через Claude API (задача или нет, исполнитель, срок, приоритет, проект; если не уверен — уточнить кнопками)'+(has('remind')?'; напоминания по cron каждые 15 минут: за сутки, за 2 часа, через час после срока, эскалация руководителю через 4 часа, тихие часы 21:00–9:00':'')+(has('kb')?'; база знаний в markdown (обо мне, проект, команда), которую ассистент сам обновляет фактами из переписки':'')+'.\\n'+\n    'Интерфейсы: '+(ui.length ? ui.join(', ') : 'только Telegram')+'.\\n'+\n    (ideas.length ? 'Дополнительно: '+ideas.map(function(i){ return i.t+' ('+i.d.replace(/\\.$/,'').toLowerCase()+')'; }).join('; ')+'.\\n' : '')+\n    '\\nНачни с этапа 1, остальное по очереди. Секреты храни в wrangler secret. Перед кодом спроси: состав команды и их Telegram, часовой пояс, какие чаты подключать, как называются проекты.';\n  $('#buildOut').innerHTML =\n    '<div class=\"sum\"><div><span>Модулей</span><b>'+(sel.length+ideas.length)+'</b></div><div><span>Доступов</span><b>'+need.length+'</b></div></div>'+\n    phases.map(function(p){ return '<div class=\"phase\"><b>'+esc(p.t)+'</b><p>'+esc(p.d)+'</p></div>'; }).join('')+\n    '<div class=\"phase\"><b>Что подготовить заранее</b><p>Нажмите на пункт, чтобы раскрыть инструкцию.</p><div class=\"accs\">'+need.map(function(n){ var st = ACCESS[n]; return st ? '<details class=\"acc\"><summary>'+esc(n)+'</summary><ol>'+st.map(function(x){ return '<li>'+x+'</li>'; }).join('')+'</ol></details>' : '<div class=\"acc plain\">'+esc(n)+'</div>'; }).join('')+'</div></div>'+\n    '<div class=\"prompt\"><div class=\"ph\"><span>Промпт для Claude Code</span><button class=\"btn sm\" id=\"copyPrompt\">Скопировать</button></div><pre class=\"file\" id=\"promptText\">'+esc(prompt)+'</pre></div>';\n  $('#copyPrompt').addEventListener('click', function(){\n    var txt = $('#promptText').textContent;\n    var ok = function(){ toast('Промпт скопирован'); };\n    var fail = function(){ var r = document.createRange(); r.selectNodeContents($('#promptText')); var s = getSelection(); s.removeAllRanges(); s.addRange(r); toast('Выделил текст, нажмите Ctrl+C'); };\n    try { navigator.clipboard.writeText(txt).then(ok, fail); } catch(err){ fail(); }\n  });\n}\nrenderMods(); renderBuild();\n\n/* ───────── Котики ───────── */\nvar CATS = [\n  {fur:'#F6A04D', dark:'#D9772A', belly:'#FFE3C2', eyes:'#2B2B33', pattern:'stripes', acc:'laptop', mood:'open',\n   name:'Котик-таргетолог', say:'CPL в норме, можно поспать', text:'Проверил кампании: всё горит только у меня в сердечке. Задачу «погладить кота» поставил тебе, срок — сейчас.'},\n  {fur:'#8E949E', dark:'#666C76', belly:'#E4E6EA', eyes:'#2B2B33', pattern:'none', acc:'glasses', mood:'open',\n   name:'Котик-аналитик', say:'У Кости опять просрочка', text:'Я посмотрел доску. У Кости обзвон висит дольше, чем я сплю днём. А сплю я много.'},\n  {fur:'#2F2F38', dark:'#1C1C22', belly:'#4A4A55', eyes:'#F2C94C', pattern:'none', acc:'bow', mood:'wink',\n   name:'Котик-эскалация', say:'Я написал руководителю', text:'Мягко напомнил, потом по делу, потом жёстко. Теперь просто сижу и смотрю. Это самая сильная эскалация.'},\n  {fur:'#FFFFFF', dark:'#E2DCD2', belly:'#FFFFFF', eyes:'#3E8EDE', pattern:'spots', acc:'coffee', mood:'open',\n   name:'Утренний котик', say:'9:00, брифинг готов', text:'Сроков сегодня три, кофе один, котик один. Начни с самого страшного, я посижу рядом.'},\n  {fur:'#C98B5A', dark:'#9E6438', belly:'#F2D6BC', eyes:'#2B2B33', pattern:'stripes', acc:'note', mood:'sleep',\n   name:'Котик тихих часов', say:'Тсс, после 21:00 не пингую', text:'Напоминания отложены до 9 утра. Если очень надо — погладь меня, я передам.'},\n  {fur:'#F2C9A0', dark:'#D9A27A', belly:'#FFF1E2', eyes:'#2B2B33', pattern:'none', acc:'crown', mood:'open',\n   name:'Котик — лидер в срок', say:'Закрыл 9 из 10 вовремя', text:'Возглавил лидерборд «в срок». Десятую задачу не закрыл, потому что на ней спал. Уважительная причина.'}\n];\nfunction catSVG(c){\n  var o = '#2B2B33';\n  var stripes = c.pattern==='stripes' ? '<path d=\"M86 52 q14 6 28 0 M80 64 q20 8 40 0\" stroke=\"'+c.dark+'\" stroke-width=\"5\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M62 132 q8 4 4 14 M138 132 q-8 4 -4 14\" stroke=\"'+c.dark+'\" stroke-width=\"6\" fill=\"none\" stroke-linecap=\"round\"/>' : '';\n  var spots = c.pattern==='spots' ? '<ellipse cx=\"70\" cy=\"62\" rx=\"14\" ry=\"11\" fill=\"#F6A04D\"/><ellipse cx=\"128\" cy=\"150\" rx=\"12\" ry=\"9\" fill=\"#2F2F38\"/>' : '';\n  var eyes;\n  if (c.mood==='sleep') eyes = '<path d=\"M72 92 q10 8 20 0 M108 92 q10 8 20 0\" stroke=\"'+o+'\" stroke-width=\"4\" fill=\"none\" stroke-linecap=\"round\"/>';\n  else if (c.mood==='wink') eyes = '<g class=\"cat-blink\"><ellipse cx=\"82\" cy=\"90\" rx=\"10\" ry=\"12\" fill=\"'+c.eyes+'\" stroke=\"'+o+'\" stroke-width=\"3\"/><circle cx=\"85\" cy=\"86\" r=\"3.5\" fill=\"#fff\"/></g><path d=\"M108 92 q10 -8 20 0\" stroke=\"'+o+'\" stroke-width=\"4\" fill=\"none\" stroke-linecap=\"round\"/>';\n  else eyes = '<g class=\"cat-blink\"><ellipse cx=\"82\" cy=\"90\" rx=\"10\" ry=\"12\" fill=\"'+c.eyes+'\" stroke=\"'+o+'\" stroke-width=\"3\"/><ellipse cx=\"118\" cy=\"90\" rx=\"10\" ry=\"12\" fill=\"'+c.eyes+'\" stroke=\"'+o+'\" stroke-width=\"3\"/><circle cx=\"85\" cy=\"86\" r=\"3.5\" fill=\"#fff\"/><circle cx=\"121\" cy=\"86\" r=\"3.5\" fill=\"#fff\"/></g>';\n  var acc = '';\n  if (c.acc==='laptop') acc = '<rect x=\"64\" y=\"150\" width=\"72\" height=\"34\" rx=\"5\" fill=\"#C7D2FE\" stroke=\"'+o+'\" stroke-width=\"3\"/><rect x=\"56\" y=\"182\" width=\"88\" height=\"8\" rx=\"3\" fill=\"#A5B4FC\" stroke=\"'+o+'\" stroke-width=\"3\"/><path d=\"M78 172 l10 -10 10 6 14 -14\" stroke=\"#2B4ACB\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/>';\n  if (c.acc==='glasses') acc = '<circle cx=\"82\" cy=\"90\" r=\"15\" fill=\"none\" stroke=\"'+o+'\" stroke-width=\"3.5\"/><circle cx=\"118\" cy=\"90\" r=\"15\" fill=\"none\" stroke=\"'+o+'\" stroke-width=\"3.5\"/><path d=\"M97 90 h6\" stroke=\"'+o+'\" stroke-width=\"3.5\"/>';\n  if (c.acc==='bow') acc = '<path d=\"M100 128 l-18 -10 v20 z M100 128 l18 -10 v20 z\" fill=\"#FF6B8B\" stroke=\"'+o+'\" stroke-width=\"3\" stroke-linejoin=\"round\"/><circle cx=\"100\" cy=\"128\" r=\"5\" fill=\"#FF6B8B\" stroke=\"'+o+'\" stroke-width=\"3\"/>';\n  if (c.acc==='coffee') acc = '<rect x=\"122\" y=\"150\" width=\"30\" height=\"34\" rx=\"6\" fill=\"#FFFFFF\" stroke=\"'+o+'\" stroke-width=\"3\"/><path d=\"M152 158 q12 2 0 16\" stroke=\"'+o+'\" stroke-width=\"3\" fill=\"none\"/><path d=\"M130 144 q4 -6 0 -12 M140 144 q4 -6 0 -12\" stroke=\"#9AA3B2\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/>';\n  if (c.acc==='note') acc = '<text x=\"140\" y=\"56\" font-family=\"Golos Text,Arial,sans-serif\" font-size=\"20\" font-weight=\"700\" fill=\"#5B4BD6\">z</text><text x=\"154\" y=\"40\" font-family=\"Golos Text,Arial,sans-serif\" font-size=\"15\" font-weight=\"700\" fill=\"#5B4BD6\">z</text>';\n  if (c.acc==='crown') acc = '<path d=\"M76 46 l8 -20 12 14 4 -18 4 18 12 -14 8 20 z\" fill=\"#F2C94C\" stroke=\"'+o+'\" stroke-width=\"3\" stroke-linejoin=\"round\"/>';\n  return '<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\">'+\n    '<path class=\"cat-tail\" d=\"M140 166 q46 -6 34 -50 q-6 -16 -14 -6 q8 26 -24 40\" fill=\"'+c.fur+'\" stroke=\"'+o+'\" stroke-width=\"3.5\" stroke-linejoin=\"round\"/>'+\n    '<ellipse cx=\"100\" cy=\"158\" rx=\"50\" ry=\"36\" fill=\"'+c.fur+'\" stroke=\"'+o+'\" stroke-width=\"3.5\"/>'+\n    '<ellipse cx=\"100\" cy=\"166\" rx=\"26\" ry=\"22\" fill=\"'+c.belly+'\"/>'+\n    '<ellipse cx=\"76\" cy=\"190\" rx=\"14\" ry=\"8\" fill=\"'+c.fur+'\" stroke=\"'+o+'\" stroke-width=\"3.5\"/><ellipse cx=\"124\" cy=\"190\" rx=\"14\" ry=\"8\" fill=\"'+c.fur+'\" stroke=\"'+o+'\" stroke-width=\"3.5\"/>'+\n    '<path d=\"M52 66 l6 -40 32 22 z\" fill=\"'+c.fur+'\" stroke=\"'+o+'\" stroke-width=\"3.5\" stroke-linejoin=\"round\"/><path d=\"M148 66 l-6 -40 -32 22 z\" fill=\"'+c.fur+'\" stroke=\"'+o+'\" stroke-width=\"3.5\" stroke-linejoin=\"round\"/>'+\n    '<path d=\"M60 58 l3 -20 15 11 z M140 58 l-3 -20 -15 11 z\" fill=\"#FFB3C1\"/>'+\n    '<ellipse cx=\"100\" cy=\"92\" rx=\"54\" ry=\"46\" fill=\"'+c.fur+'\" stroke=\"'+o+'\" stroke-width=\"3.5\"/>'+\n    stripes + spots + eyes +\n    '<ellipse cx=\"66\" cy=\"108\" rx=\"9\" ry=\"5.5\" fill=\"#FF9BB0\" opacity=\".7\"/><ellipse cx=\"134\" cy=\"108\" rx=\"9\" ry=\"5.5\" fill=\"#FF9BB0\" opacity=\".7\"/>'+\n    '<path d=\"M95 104 h10 l-5 6 z\" fill=\"#FF7A95\" stroke=\"'+o+'\" stroke-width=\"2\" stroke-linejoin=\"round\"/>'+\n    '<path d=\"M100 110 q-6 9 -12 3 M100 110 q6 9 12 3\" stroke=\"'+o+'\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/>'+\n    '<path d=\"M62 100 h-22 M62 108 l-20 5 M138 100 h22 M138 108 l20 5\" stroke=\"'+o+'\" stroke-width=\"2.5\" stroke-linecap=\"round\"/>'+\n    acc + '</svg>';\n}\nvar catCur = -1, catHideT = null, catTimer = null;\nfunction pickCat(){ var i; do { i = Math.floor(Math.random()*CATS.length); } while (CATS.length>1 && i===catCur); catCur = i; return CATS[i]; }\nfunction showCat(){\n  if (!$('#catModal').hidden) return;\n  var c = pickCat(), dock = $('#catDock');\n  dock.classList.remove('out','left','right'); dock.classList.add(Math.random()<.5 ? 'left' : 'right');\n  $('#catPeek').innerHTML = catSVG(c); $('#catSay').textContent = c.say;\n  dock.hidden = false; void dock.offsetWidth;\n  clearTimeout(catHideT); catHideT = setTimeout(hideCat, 30000);\n}\nfunction hideCat(){ var dock = $('#catDock'); if (dock.hidden) return; dock.classList.add('out'); setTimeout(function(){ dock.hidden = true; dock.classList.remove('out'); }, 450); }\nfunction openCat(c){\n  c = c || CATS[catCur] || pickCat();\n  $('#catBig').innerHTML = catSVG(c); $('#catTitle').textContent = c.name; $('#catText').textContent = c.text;\n  $('#catModal').hidden = false; $('#catDock').hidden = true; clearTimeout(catHideT);\n}\nfunction closeCat(){ $('#catModal').hidden = true; }\n$('#catPeek').addEventListener('click', function(){ openCat(); });\n$('#catX').addEventListener('click', hideCat);\n$('#catClose').addEventListener('click', closeCat);\n$('#catOk').addEventListener('click', closeCat);\n$('#catMore').addEventListener('click', function(){ openCat(pickCat()); });\n$('#catModal').addEventListener('click', function(e){ if (e.target === this) closeCat(); });\ndocument.addEventListener('keydown', function(e){ if (e.key==='Escape' && !$('#catModal').hidden) closeCat(); });\nsetTimeout(showCat, 15000);\ncatTimer = setInterval(showCat, 5*60*1000);\n\n/* ───────── старт ───────── */\nrenderBoard(); runParse();\n\n})();\n</script>\n</body>\n</html>\n";
